INSERT INTO `intangible_cultural_heritage` VALUES (113,'京剧','传统戏曲','京剧艺术','清代','北京','','适合沉浸式感受京味戏曲表演与脸谱文化。','京剧起源于清代，1790年（乾隆五十五年）为给乾隆皇帝祝寿，扬州盐商组织徽班进京演出。此后，其他徽班相继入京，形成四大徽班。道光年间，汉调艺人加入，形成徽汉合流，京剧由此诞生。历经200多年发展，成为中国戏曲的集大成者。','京剧作为中国文化的瑰宝，对构建中华民族精神家园有不可替代的作用。京剧的传承延续着科班体系、家族血脉、师徒门户的活态传承网络。京剧的唱腔、表演、脸谱、服饰具有独特艺术价值，是中华民族艺术殿堂里的璀璨明珠。','梅兰芳（梅派）、程砚秋（程派）、荀慧生（荀派）、尚小云（尚派）、谭富英（谭派）、马连良（马派）等国家级传承人',NULL,NULL,'[\"《京剧》清·爱新觉罗·弘历 徽调汉调聚京城，梨园子弟竞纷呈。 生旦净丑皆成戏，唱念做打见真情。\"]','[\"立春\", \"雨水\", \"惊蛰\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:11'),(114,'景泰蓝制作技艺','传统手工艺','金属珐琅工艺','清代','北京','','适合体验掐丝点蓝的宫廷器物制作。','景泰蓝又称\"铜胎掐丝珐琅\"，因在明代景泰年间制作技艺最为成熟，且多用蓝色釉料而得名。其起源可追溯到元代，由阿拉伯地区传入中国。明清时期，景泰蓝成为宫廷御用工艺品，景泰年间达到鼎盛。','景泰蓝体现了中国传统工艺美术的最高水平，是金属胎珐琅器制作技艺的杰出代表。其制作过程融合了青铜工艺、绘画、雕刻等多种艺术形式，具有极高的历史、艺术和科学价值。景泰蓝的传承对于研究中国古代工艺美术具有重要意义。','钱美华（特国家级）、钟连盛（国家级）、李静（国家级）等景泰蓝制作技艺传承人',NULL,NULL,'[\"《景泰蓝》明·佚名 嵌丝点蓝出宫墙，铜胎金骨韵悠长。 景泰年间臻至美，千秋万代永流芳。\"]','[\"立秋\", \"白露\", \"寒露\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:11'),(115,'北京面塑','传统手工艺','面塑艺术','清代','北京','','适合亲手制作节庆面塑与民俗造型。','北京面塑历史悠久，起源于古代祭祀活动中用面粉捏制的供品。清代中后期，面塑艺术在京城民间广泛流传，成为节庆民俗活动的重要组成部分。民间艺人用面粉、糯米粉等原料，捏制各种人物、动物造型，色彩鲜艳，形象生动。','北京面塑是北方民间艺术的代表，体现了老北京人的生活智慧和审美情趣。面塑作品题材广泛，包括戏曲人物、神话传说、花鸟虫鱼等，具有重要的民俗学研究价值。面塑技艺的传承延续着师徒口传心授的方式。','曹珩（面塑艺术家）、张宝琳（面塑艺术家）、冯海瑞（面塑艺术家）等北京面塑传承人',NULL,NULL,'[\"《面塑》清·民间 巧手捏出万象生，五彩纷呈庆太平。 传承百年今犹在，非遗技艺永流芳。\"]','[\"春节\", \"元宵节\", \"清明\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:11'),(116,'宫灯制作技艺','传统手工艺','灯彩扎制','明代','北京','','适合节庆夜游场景与灯彩手作体验。','宫灯起源于东汉时期，盛行于明清两代。因专为宫廷使用而得名，造型华贵，制作精良。主要有四方灯、六方灯、八方灯、圆灯等造型，以红木、紫檀、花梨等名贵木材为框架，配以丝绢、玻璃等材料制作灯罩，内燃蜡烛，光彩夺目。','宫灯是中国传统照明艺术与建筑艺术的完美结合，体现了中国传统工艺美术的最高水平。其制作涉及木工、雕刻、绘画、刺绣等多个工艺门类，具有重要的历史、艺术和文化价值。宫灯文化承载着中华民族的审美追求和精神寄托。','梁俊生（宫灯传承人）、翟文德（宫灯传承人）等宫灯制作技艺传承人',NULL,NULL,'[\"《宫灯》明·高启 宫灯高悬照华堂，红烛摇光夜未央。 千年技艺今犹在，万盏灯火映辉煌。\"]','[\"元宵节\", \"春节\", \"中秋\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:11'),(117,'风筝制作技艺','传统手工艺','风筝扎制','清代','北京','','适合春日户外体验和传统彩绘工艺。','风筝古称\"纸鸢\"或\"鹞子\"，起源于春秋战国时期，相传为墨子所创。汉代发明纸张后，纸鸢逐渐流行。唐宋时期，风筝制作技艺日趋成熟，造型多样，放飞技巧不断完善。清代达到鼎盛，各地形成不同风格的风筝流派。','风筝是中国古代四大发明之一——造纸术的延伸应用，体现了中国古代人民的智慧创造力。风筝制作涉及材料学、空气动力学等多个学科，具有重要的科学研究价值。风筝文化承载着人们对美好生活的向往，具有重要的民俗学价值。','哈亦琦（国家级）、王赤丹（国家级）、赵伟强（国家级）等风筝制作技艺传承人',NULL,NULL,'[\"《纸鸢》宋·寇准 碧落秋方静，腾空力尚微。 如何清风夕，拈弄得游依。\"]','[\"清明\", \"春分\", \"谷雨\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:11'),(118,'苏绣','传统手工艺','刺绣艺术','宋代','江苏','','适合感受宋韵针法与江南审美。','苏绣发源于苏州地区，距今已有四千多年历史。早在春秋时期，吴地已有刺绣活动。明清时期，苏绣达到鼎盛，形成了图案秀丽、色彩典雅、针法活泼、绣工精细的艺术风格，与湘绣、蜀绣、粤绣并称中国四大名绣。','苏绣是江南文化的杰出代表，体现了中国传统刺绣艺术的最高水平。苏绣针法丰富多样，有齐针、套针、戗针、乱针等四十多种针法。苏绣作品题材广泛，包括人物、山水、花鸟等，具有重要的艺术研究价值和收藏价值。','姚建萍（国家级）、王丽华（省级）、林怡（省级）等苏绣传承人',NULL,NULL,'[\"《绣》明·唐寅 荷开并蒂艳，莲结同心双。 针下生花处，人间第一香。\"]','[\"春分\", \"清明\", \"谷雨\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:11'),(119,'南戏昆山腔','传统戏曲','昆曲表演','宋代','江苏','','适合体验宋韵戏曲声腔与舞台身段。','南戏昆山腔简称昆腔，又称昆曲、昆剧，起源于元末明初的江苏昆山地区。明嘉靖年间，戏曲音乐家魏良辅改革昆山腔，吸收海盐腔、余姚腔的优点，创立委婉细腻的\"水磨腔\"。昆曲以其优美的唱腔和文雅的剧词被誉为\"百戏之祖\"。','昆曲是中国现存最古老的剧种之一，被誉为\"活化石\"。昆曲的唱腔婉转悠扬，行腔优美，水磨调细腻柔和。昆曲文学价值极高，《牡丹亭》《长生殿》等剧作成为中国文学史上的经典。昆曲对京剧及各地方剧种的形成产生了深远影响。','梁辰（昆曲传承人）、王芳（昆曲传承人）、张军（昆曲传承人）、沈昳丽（昆曲传承人）等昆曲传承人',NULL,NULL,'[\"《昆曲》明·汤显祖 情不知所起，一往而深，生者可以死，死可以生。\"]','[\"春分\", \"清明\", \"谷雨\", \"立夏\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:11'),(120,'南京云锦','传统手工艺','丝织工艺','宋代','江苏','','适合了解古代织造工艺与纹样设计。','南京云锦始于元代，盛于明清，因其色泽灿烂如天际云霞而得名。南京云锦是皇家御用贡品，专为宫廷织造。龙袍、官服、宫廷装饰等均用云锦制作。云锦织造工艺复杂，需由拽花工和织手两人配合，一天只能织造五六厘米。','南京云锦是中国丝织工艺的巅峰之作，代表了中国织锦技艺的最高水平。云锦图案丰富多彩，有龙凤、花鸟、祥云、福寿等纹样，色彩艳丽和谐。云锦织造技艺无法用现代机器完全替代，其传承对于研究中国古代丝织技术具有重要意义。','周双喜（国家级）、朱枫（省级）、郭俊（省级）等南京云锦传承人',NULL,NULL,'[\"《云锦》清·曹雪芹 缂织金缕织云霞，锦绣文章耀中华。 非遗技艺传千载，匠心独运绽奇葩。\"]','[\"立秋\", \"白露\", \"秋分\", \"寒露\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:11'),(121,'桃花坞木版年画','传统美术','木版年画','明代','江苏','','适合春节主题路线和木版印制体验。','桃花坞木版年画始于明代，起源于苏州桃花坞地区，因地得名。清代康乾年间达到鼎盛，成为中国木版年画的代表之一。桃花坞年画风格独特，构图丰满，色彩鲜艳，题材多为门神、仕女、娃娃、山水、花鸟等，具有浓郁江南水乡特色。','桃花坞木版年画是江南民间艺术的杰出代表，体现了中国农耕社会的审美观念和民俗信仰。年画寄托了人们对美好生活的向往，具有重要的民俗学研究价值。其雕版和印刷技艺对于研究中国传统印刷术具有重要的参考价值。','王文瑛（国家级）、房志达（国家级）、叶小芬（省级）等桃花坞木版年画传承人',NULL,NULL,'[\"《年画》清·民间 桃红柳绿映春光，年画贴在门楣上。 驱邪纳福保平安，吉祥如意福满堂。\"]','[\"春节\", \"立春\", \"元宵节\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:11'),(122,'秦淮灯彩','传统美术','灯彩艺术','宋代','江苏','','适合节庆夜游和灯彩制作路线。','秦淮灯彩历史悠久，起源于六朝时期，盛行于明代。朱元璋定都南京后，秦淮河畔每年元宵节举办灯会，灯火辉煌，蔚为壮观。秦淮灯彩以扎工精巧、色彩绚丽、品种繁多而闻名，有宫灯、纱灯、花灯、动物灯等数千个品种。','秦淮灯彩是南京历史文化的重要组成部分，体现了江南水乡的民俗风情和审美情趣。灯彩制作涉及扎作、裱糊、绘画、剪纸等多种工艺，具有重要的艺术价值。秦淮灯会已成为国家级非物质文化遗产，是元宵节最重要的民俗活动之一。','郑峰（省级）、徐水保（省级）、王庆喜（省级）等秦淮灯彩传承人',NULL,NULL,'[\"《秦淮灯影》明·朱元璋 秦淮河畔月华明，万盏灯火照古城。 疑是银河落人间，疑是繁星落金陵。\"]','[\"元宵节\", \"春节\", \"中秋\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:11'),(123,'宣纸制作技艺','传统手工艺','造纸工艺','唐代','安徽','','适合深度体验文房四宝的材料工艺。','宣纸产于安徽宣城地区，因唐代时属宣州府而得名。宣纸始创于唐代，宋代达到鼎盛，被指定为宫廷用纸。宣纸以青檀皮和沙田稻草为原料，经浸泡、蒸煮、捣浆、抄纸等十八道工序，需一年以上时间才能制成。','宣纸是中国文房四宝之首，具有\"纸寿千年\"的美誉。宣纸质地绵韧、纹理清晰、不蛀不腐，是书画创作的最佳载体。宣纸制作技艺是中国传统造纸术的杰出代表，对中国书法绘画艺术的传承具有不可替代的作用。','邢春荣（国家级）、张建平（省级）、戴曦（省级）等宣纸制作技艺传承人',NULL,NULL,'[\"《宣纸》唐·韩愈 宣城出佳纸，质地柔且坚。 落笔惊风雨，书画永流传。\"]','[\"立秋\", \"白露\", \"寒露\", \"霜降\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:11'),(124,'歙砚制作技艺','传统手工艺','砚石雕刻','宋代','安徽','','适合体验砚石选材与雕刻工艺。','歙砚产于安徽歙县地区，因唐宋时期属歙州而得名。歙砚始于唐代，至今已有一千多年历史。宋代达到鼎盛，与端砚、洮砚、澄泥砚并称中国四大名砚。歙砚石质细腻温润，发墨如油，研出的墨汁不沾不涴。','歙砚是中国文房四宝之一，具有\"石渠名渊\"的美誉。歙砚制作涉及选石、设计、雕刻、打磨等数十道工序，雕刻题材丰富多样，包括山水、人物、花鸟、瑞兽等。歙砚不仅是实用文具，更是精美的艺术品，具有重要的收藏价值。','胡震华（国家级）、方建新（省级）、吴振华（省级）等歙砚制作技艺传承人',NULL,NULL,'[\"《歙砚》宋·苏轼 涩不留笔，滑不拒墨。 瓜肤而縠理，金声而玉德。\"]','[\"立冬\", \"小雪\", \"大雪\", \"冬至\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:11'),(125,'徽墨制作技艺','传统手工艺','徽墨制作','宋代','安徽','','适合串联笔墨纸砚主题路线。','徽墨产于安徽徽州地区，因唐宋时期属徽州府而得名。徽墨始于唐代，宋代达到鼎盛，成为文人墨客必备之物。徽墨以松烟、桐油烟为原料，配以麝香、冰片等名贵药材，经炼烟、和料、压模、描金等数十道工序制成。','徽墨是中国文房四宝之一，具有\"落纸如漆、万载存真\"的美誉。徽墨色泽黑润、香味浓郁、质地细腻，是书法绘画的绝佳用品。徽墨制作技艺融合了制墨、雕刻、书法、绘画等多种艺术形式，具有重要的文化价值。','项德兴（国家级）、冯良才（省级）、朱建新（省级）等徽墨制作技艺传承人',NULL,NULL,'[\"《徽墨》宋·欧阳修 徽墨落纸云烟起，芳香四溢满书房。 千年传承工艺绝，文化瑰宝永流芳。\"]','[\"立秋\", \"白露\", \"秋分\", \"寒露\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:11'),(126,'糖画','传统手工艺','糖塑艺术','清代','四川','','适合亲子与节庆街区体验。','糖画起源于明代，起源于四川地区，后流传全国。糖画艺人以糖稀为原料，用铜勺舀起糖浆，在石板或大理石上徒手绘制各种图案。糖画题材广泛，有龙凤、花鸟、人物、戏曲等，色彩金黄透明，深受儿童喜爱。','糖画是中国传统的民间艺术，融合了绘画、雕塑、工艺美术等多种元素。糖画制作讲究\"眼明手快\"，一气呵成，具有独特的艺术魅力。糖画承载着人们对甜蜜美好生活的向往，是春节庙会等民俗活动中不可或缺的组成部分。','蔡雪静（省级）、陈定兴（省级）等糖画传承人',NULL,NULL,'[\"《糖画》清·民间 金勺舀出万般形，甜蜜蜜中见真情。 童年记忆永难忘，非遗技艺代代传。\"]','[\"春节\", \"元宵节\", \"清明\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:11'),(127,'川剧变脸','传统戏曲','戏曲变脸','清代','四川','','适合夜间剧场和互动表演路线。','川剧变脸是川剧表演艺术中最具特色的绝技之一，起源于清代中后期。川剧艺人运用抹脸、吹脸、扯脸等技法，在刹那间变换面部色彩和图案，令人叹为观止。变脸技艺经过几代艺人的不断创新和发展，已成为川剧的代表性符号。','川剧变脸是中国戏曲艺术中最神秘、最精彩的表演技艺之一，体现了川剧艺人高超的表演技巧和深厚的艺术功底。变脸技艺是戏曲艺术与魔术技巧的完美结合，具有极高的观赏价值和艺术研究价值。其传承遵循严格的师徒制度。','彭登怀（变脸传承人）、肖德美（变脸传承人）、刘谊（变脸传承人）等川剧变脸传承人',NULL,NULL,'[\"《川剧变脸》近现代·佚名 脸谱变幻一瞬间，红蓝白紫任调迁。 川剧绝技惊天下，艺海无涯苦作舟。\"]','[\"春分\", \"清明\", \"夏至\", \"立秋\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:11'),(128,'蜀绣','传统手工艺','刺绣艺术','宋代','四川','','适合体验细腻针法与色彩层次。','蜀绣又名\"川绣\"，起源于四川地区，距今已有数千年的历史。据记载，西汉时期蜀绣已相当发达，成为宫廷贡品。蜀绣以成都为中心，针法独特，有套针、晕针、斜滚针、旋流针等一百多种针法，形成了自己独特的艺术风格。','蜀绣是中国四大名绣之一，具有图案秀丽、色彩明快、线条流畅、针法独特的特点。蜀绣绣品题材广泛，包括人物、山水、花鸟、鱼虫等，具有重要的艺术价值。蜀绣技艺的传承对于研究巴蜀文化具有重要意义。','郝淑萍（国家级）、杨德琼（省级）、孟德芝（省级）等蜀绣传承人',NULL,NULL,'[\"《蜀绣》唐·贾岛 蜀地文章冠四方，绣娘巧手织云裳。 芙蓉锦帐春无限，针下生花万古香。\"]','[\"春分\", \"清明\", \"谷雨\", \"立夏\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:11'),(129,'青神竹编','传统手工艺','竹编工艺','唐代','四川','','适合安排手作课程与山水线路结合。','青神竹编起源于四川青神县，已有两千多年历史。青神竹编以当地盛产的慈竹为原料，经破竹、刮青、分篾、拉丝等工序，编织成各种生活用品和工艺品。青神竹编造型精美，工艺精湛，兼具实用性和艺术性。','青神竹编是中国竹编工艺的杰出代表，体现了古代劳动人民的智慧和创造力。竹编制作涉及选竹、破竹、分篾、刮丝、编织等多道工序，每道工序都有严格要求。青神竹编对于研究中国传统竹编工艺具有重要的参考价值。','陈云华（国家级）、张德明（省级）、吴晓红（省级）等青神竹编传承人',NULL,NULL,'[\"《竹编》唐·杜甫 竹斋闻水声，编竹为篱墙。 此地一为别，孤蓬万里征。\"]','[\"立夏\", \"小满\", \"芒种\", \"夏至\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:11'),(130,'唐墓壁画临摹技艺','传统美术','壁画临摹','唐代','陕西','','适合沉浸体验盛唐壁画线描与设色。','唐墓壁画临摹技艺始于唐代，历代均有传承。唐墓壁画是研究唐代社会生活的重要资料，内容涉及宴饮、出行、乐舞、狩猎等各个层面。临摹技艺通过专业艺人的观察和实践，将原作的笔触、色彩、构图等完美复制，为壁画保护和研究提供了重要手段。','唐墓壁画临摹技艺是保护和研究古代壁画的重要手段，对于传承中华优秀传统文化具有重要意义。临摹作品不仅保存了壁画的信息，还为壁画的展示和传播提供了可能。临摹技艺要求艺人具备扎实的绘画功底和丰富的历史知识。','王建平（唐墓壁画临摹传承人）、刘向红（唐墓壁画临摹传承人）等唐墓壁画临摹技艺传承人',NULL,NULL,'[\"《观唐墓壁画》唐·白居易 墓室幽深画满墙，唐风古韵墨犹香。 千年往事今犹在，一壁丹青记盛唐。\"]','[\"清明\", \"谷雨\", \"立夏\", \"夏至\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:11'),(131,'碑刻传拓技艺','传统美术','碑刻技艺','唐代','陕西','','适合文博型游客体验传拓与碑刻艺术。','碑刻传拓技艺起源于南北朝时期，是中国古代复制石碑文字和图案的传统技法。传拓艺人用宣纸覆盖碑刻，用墨轻轻捶打，使纸面紧贴碑面，呈现碑刻的阴刻效果。传拓作品忠实保留了碑刻的文字和图案，是金石学研究的重要的基础资料。','碑刻传拓技艺是中华文化遗产保护的重要手段，对于保存和传播古代碑刻艺术具有重要意义。传拓作品可以反复捶制，便于携带和保存，是研究古代书法、篆刻、历史的重要资料。传拓技艺的传承对于金石学的发展具有重要价值。','李浩（国家级）、程造之（省级）、张建（省级）等碑刻传拓技艺传承人',NULL,NULL,'[\"《传拓》清·翁方纲 金石永年存古意，纸墨相发见精神。 传拓技艺承千载，金石学研究有来人。\"]','[\"立秋\", \"白露\", \"秋分\", \"寒露\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:11'),(132,'长安宫灯彩绘','传统美术','灯彩彩绘','唐代','陕西','','适合节庆主题路线和唐风灯彩体验。','长安宫灯彩绘起源于唐代长安地区，是宫廷灯彩装饰的重要技法。唐代长安是当时的国际大都市，宫廷灯彩华丽精美，彩绘技艺精湛。宫灯彩绘融合了绘画、雕刻、刺绣等多种艺术形式，体现了盛唐时期的审美追求。','长安宫灯彩绘是唐代工艺美术的杰出代表，体现了盛唐时期的文化繁荣和艺术成就。彩绘图案以祥云、龙凤、花鸟为主，色彩艳丽和谐，具有重要的艺术价值。宫灯彩绘技艺的传承对于研究唐代工艺美术具有重要意义。','王学文（省级）、曹辛（省级）等长安宫灯彩绘传承人',NULL,NULL,'[\"《长安灯》唐·苏味道 火树银花合，星桥铁锁开。 暗尘随马去，明月逐人来。\"]','[\"元宵节\", \"春节\", \"中秋\", \"重阳节\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:11'),(133,'苗绣','传统手工艺','苗族刺绣','清代','贵州','','适合少数民族主题深度路线。','苗绣是苗族妇女的传统刺绣技艺，已有数千年的历史。苗族没有文字，苗绣成为记录民族历史和文化的重要载体。苗绣图案题材广泛，有蝴蝶妈妈、龙、鸟、鱼、花等，色彩鲜艳，对比强烈，具有浓郁的民族特色。','苗绣是苗族文化的\"无字史书\"，承载着苗族的历史传说和审美观念。苗绣图案富有深意，如蝴蝶妈妈是苗族神话中的祖先，苗绣的传承对于研究苗族文化具有重要意义。苗绣技法独特，有平绣、锁绣、绉绣、打籽绣等数十种针法。','王阿勇（国家级）、吴通贤（省级）、杨阿扭（省级）等苗绣传承人',NULL,NULL,'[\"《苗绣》现代·佚名 蝴蝶妈妈传千年，银线绣出故园天。 针针线线皆情意，苗家儿女代代传。\"]','[\"春分\", \"清明\", \"谷雨\", \"芒种\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:11'),(134,'苗族银饰锻制技艺','传统手工艺','银饰锻造','清代','贵州','','适合与节庆服饰文化一起体验。','苗族银饰锻制技艺历史悠久，是苗族文化的重要组成部分。苗族银饰包括头饰、颈饰、胸饰、手饰等，造型精美，工艺精湛。苗族银饰不仅是装饰品，更是财富和身份的象征，在苗族传统节日和婚嫁等重要场合不可或缺。','苗族银饰锻制技艺是苗族工艺美术的杰出代表，体现了苗族人民的审美情趣和工艺水平。银饰制作涉及铸炼、锻打、焊接、雕刻、洗涤等数十道工序，每道工序都有严格要求。苗族银饰承载着苗族的历史传说和文化记忆。','杨光金（国家级）、龙米谷（省级）、吴通福（省级）等苗族银饰锻制技艺传承人',NULL,NULL,'[\"《苗族银饰》现代·佚名 银花朵朵头上开，叮当作响踏歌来。 苗家姑娘多美丽，银饰辉映百花开。\"]','[\"春节\", \"清明\", \"端午节\", \"苗年\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:11'),(135,'壮锦织造技艺','传统手工艺','壮锦织造','清代','广西','','适合壮乡主题路线和织机体验。','壮锦是壮族人民的传统手工艺品，起源于宋代，有一千多年的历史。壮锦以棉纱为经、丝线为纬，用腰机手工织造。壮锦图案题材广泛，有几何纹、动物纹、植物纹、人物纹等，色彩鲜艳，对比强烈，具有浓郁的壮族特色。','壮锦是壮族文化的杰出代表，被誉为\"中国四大名锦\"之一。壮锦织造技艺是壮族妇女世代相传的传统手工艺，体现了壮族人民的审美情趣和创造能力。壮锦图案富有深意，是壮族文化的重要载体。','谭湘光（国家级）、李村灵（省级）、覃奶卓（省级）等壮锦织造技艺传承人',NULL,NULL,'[\"《壮锦》现代·佚名 壮家儿女心灵巧，织出彩虹满山坡。 经纬交织千年梦，壮锦灿烂耀山河。\"]','[\"春分\", \"清明\", \"谷雨\", \"芒种\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:11'),(136,'铜鼓习俗','传统民俗','铜鼓文化','清代','广西','','适合民俗节庆和少数民族主题串联。','铜鼓是中国南方和西南地区少数民族的打击乐器，起源于春秋战国时期，距今已有两千多年历史。铜鼓造型庄重，纹饰精美，是权力和财富的象征。铜鼓在壮族、苗族、瑶族、布依族等民族中广泛使用，主要用于祭祀、节庆和丧葬等场合。','铜鼓是中国南方少数民族文化的重要标志，具有重要的历史、艺术和科学研究价值。铜鼓纹饰内容丰富，有太阳纹、云雷纹、舞蹈纹、竞渡纹等，是研究古代南方民族社会生活的重要资料。铜鼓习俗的传承对于维护民族文化多样性具有重要意义。','蒙土金（国家级）、韦启军（省级）、莫清辉（省级）等铜鼓习俗传承人',NULL,NULL,'[\"《铜鼓》唐·柳宗元 铜鼓声中岁又除，蛮歌野舞庆有余。 击鼓其镗壮士起，铜鼓习俗代代传。\"]','[\"春节\", \"清明\", \"端午节\", \"中秋\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:11'),(137,'杨柳青年画','传统美术','木版年画','清代','天津','','适合春节主题路线和民艺版画体验。','杨柳青年画始于明代崇祯年间，产于天津杨柳青镇，因地得名。杨柳青年画以木版印刷与人工彩绘相结合，形成独特的艺术风格。年画题材广泛，有门神、仕女、娃娃、戏曲等，色彩艳丽，形象生动，富有浓郁的民间生活气息。','杨柳青年画是中国木版年画的杰出代表，与桃花坞年画并称\"南桃北柳\"。杨柳青年画将木版印刷与手工彩绘完美结合，体现了民间艺人的创造智慧。年画寄托了人们对美好生活的向往，具有重要的民俗学研究价值。','霍庆顺（国家级）、霍庆林（省级）等杨柳青年画传承人',NULL,NULL,'[\"《杨柳青年画》清·民间 年画贴在门楣上，驱邪纳福保平安。 杨柳青青映春色，吉祥如意满人间。\"]','[\"春节\", \"立春\", \"元宵节\", \"清明\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:11'),(138,'泥人张彩塑','传统美术','泥塑彩绘','清代','天津','','适合春节场景和彩塑手作。','泥人张彩塑起源于清代道光年间，由天津民间艺人张明山创立。张明山技艺精湛，只需与人对坐顷刻，便能将人物形象捏塑出来，形神兼备。泥人张彩塑以戏曲人物、历史人物、民间故事为题材，色彩艳丽，造型生动，富有浓郁的生活气息。','泥人张彩塑是天津民间艺术的杰出代表，被誉为\"立体的画，无声的戏\"。泥人张彩塑将泥塑与彩绘完美结合，形成独特的艺术风格。泥人张作品题材广泛，形象逼真，具有重要的艺术价值和研究价值。','张明山（泥人张创始人）、张玉祺（第二代）、张钫（第三代）等泥人张彩塑传承人',NULL,NULL,'[\"《泥人张》清·民间 捏出人间百态形，彩塑泥人最传情。 津门绝技惊天下，栩栩如生见真功。\"]','[\"清明\", \"谷雨\", \"立夏\", \"夏至\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:11'),(139,'潍坊风筝','传统手工艺','风筝扎制','宋代','山东','','适合清明踏青路线和风筝扎制体验。','潍坊风筝历史悠久，始于明代，盛于清代。潍坊古称\"鸢都\"，是中国风筝的发源地之一。潍坊风筝造型独特，放飞性能优良，有\"放到天上是风景，收在手里是艺术\"的美誉。潍坊风筝种类繁多，有板子风筝、立体风筝、软翅风筝等。','潍坊风筝是中国风筝的杰出代表，与北京风筝南北呼应。潍坊风筝制作涉及选材、绑扎、绘画、拴线等工序，每道工序都有严格要求。潍坊风筝融合了力学、美学、工艺学等知识，具有重要的科学研究价值。','郭洪利（国家级）、张效东（省级）、刘志斌（省级）等潍坊风筝传承人',NULL,NULL,'[\"《风筝》清·郑板桥 纸鸢纷纷四月天，东风阵阵放飞鸢。 儿童散学归来早，忙趁东风放纸鸢。\"]','[\"清明\", \"春分\", \"谷雨\", \"立夏\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:11'),(140,'山东剪纸','传统手工艺','剪纸艺术','清代','山东','','适合节庆装饰与手工体验。','山东剪纸历史悠久，源于山东民间，有一千多年的历史。山东剪纸分为胶东窗花和鲁西北剪纸两大流派。胶东窗花造型简洁，线条粗犷；鲁西北剪纸则细腻精致，构图繁复。山东剪纸题材广泛，有花鸟虫鱼、人物戏曲、吉祥图案等。','山东剪纸是山东民间艺术的杰出代表，体现了山东人民的审美情趣和精神追求。剪纸作品寄托了人们对美好生活的向往，具有重要的民俗学研究价值。山东剪纸技法独特，有单色剪纸、套色剪纸、分色剪纸等多种形式。','范祚信（国家级）、赵爱华（省级）、林伟红（省级）等山东剪纸传承人',NULL,NULL,'[\"《剪纸》清·民间 巧手剪出万象生，红纸片片见真情。 剪下生花千万朵，非遗技艺永流芳。\"]','[\"春节\", \"元宵节\", \"清明\", \"端午节\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:11'),(141,'唐三彩','传统手工艺','陶俑烧制','唐代','河南','','适合古都审美与陶艺体验。','唐三彩是唐代盛行的低温釉陶器，因常用黄、绿、白三种釉色而得名。唐三彩主要用于随葬明器，造型多样，有人物、动物、生活器皿等。唐三彩造型生动，色彩艳丽，反映了唐代社会的繁荣景象和开放包容的文化氛围。','唐三彩是中国陶瓷史上的瑰宝，被誉为\"唐代社会生活的百科全书\"。唐三彩造型丰富多样，有文臣武士、仕女童子、胡人驼马、镇墓兽等，反映了唐代社会的方方面面。唐三彩对后世陶瓷艺术产生了深远影响。','刘淑侠（国家级）、张怀义（省级）等唐三彩传承人',NULL,NULL,'[\"《唐三彩》唐·白居易 彩釉斑斓耀盛唐，三彩陶俑韵悠长。 千姿百态人欢笑，丝路风情入画堂。\"]','[\"清明\", \"谷雨\", \"立夏\", \"夏至\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:11'),(142,'龙泉青瓷烧制技艺','传统手工艺','青瓷烧制','宋代','浙江','','适合器物审美和青瓷烧制体验。','龙泉青瓷始于三国两晋时期，在宋代达到鼎盛。龙泉窑是中国古代五大名窑之一，以烧制青瓷著称。龙泉青瓷釉色青翠温润，有\"梅子青\"、\"粉青\"等名贵釉色。龙泉青瓷造型端庄典雅，釉面光洁如玉，被誉为\"瓷器之花\"。','龙泉青瓷是中国瓷器史上的巅峰之作，体现了中国传统美学的最高境界。龙泉青瓷烧制技艺涉及选料、成型、上釉、烧制等多道工序，每道工序都有严格要求。龙泉青瓷对韩国、日本等周边国家的瓷器发展产生了深远影响。','徐朝兴（国家级）、陈爱明（省级）、周华（省级）等龙泉青瓷烧制技艺传承人',NULL,NULL,'[\"《龙泉青瓷》宋·苏轼 夺得千峰翠色来，梅子青时最堪爱。 龙泉古窑烧青瓷，千秋万代永流芳。\"]','[\"立夏\", \"小满\", \"芒种\", \"夏至\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:11'),(143,'王星记制扇技艺','传统手工艺','制扇工艺','明代','浙江','','适合文人器物主题路线。','王星记扇子始创于清光绪年间，由杭州扇艺师王星斋创立。王星记扇子以做工精细、选料考究、品种繁多而闻名，有黑纸扇、檀香扇、白纸扇、绢扇等数十个品种。王星记扇子既是实用品，又是工艺品，被誉为\"东方艺术之花\"。','王星记制扇技艺是杭州传统手工艺的杰出代表，体现了中国传统扇艺的最高水平。制扇技艺涉及选竹、破扇、制骨、糊面、绘画等多道工序，每道工序都有严格要求。王星记扇子承载着丰富的文化内涵，具有重要的艺术价值。','孙亚青（国家级）、丁光洪（省级）等王星记制扇技艺传承人',NULL,NULL,'[\"《扇》唐·白居易 银字笙寒调正丝，水纹帘影傍身垂。 轻摇小扇生凉意，一缕清风入梦来。\"]','[\"立夏\", \"小满\", \"芒种\", \"夏至\", \"大暑\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:11'),(144,'广绣','传统手工艺','岭南刺绣','清代','广东','','适合岭南题材刺绣与商都漫游。','广绣是广州地区的传统刺绣技艺，包括广州刺绣和潮州刺绣两大流派。广绣历史悠久，起源于唐代，鼎盛于明清。广绣针法独特，有套针、戗针、勒针、编针等数十种针法，色彩鲜艳，立体感强，富有岭南特色。','广绣是中国四大名绣之一，具有图案繁茂、色彩艳丽、立体感强、金银线运用等特点。广绣作品题材广泛，包括花鸟虫鱼、人物山水、吉祥图案等，具有重要的艺术价值。广绣技艺的传承对于研究岭南文化具有重要意义。','陈少芳（国家级）、谭展鹏（省级）、梁雪珍（省级）等广绣传承人',NULL,NULL,'[\"《广绣》清·屈大均 粤绣精巧天下闻，针飞线舞织春云。 岭南风采入画轴，千红万紫总是春。\"]','[\"春分\", \"清明\", \"谷雨\", \"立夏\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:11'),(145,'潮州木雕','传统手工艺','木雕艺术','明代','广东','','适合工艺细作和古城漫游结合。','潮州木雕发源于广东潮州地区，起源于唐代，鼎盛于明清。潮州木雕以浮雕、沉雕、圆雕、通雕等技法著称，题材广泛，有人物故事、花鸟虫鱼、祥禽瑞兽、几何纹样等。潮州木雕构图繁密，层次丰富，精细入微，被誉为\"中国木雕艺术的明珠\"。','潮州木雕是中国木雕艺术的杰出代表，具有重要的艺术价值和历史价值。潮州木雕作品多用于建筑装饰、家具装饰和工艺品制作，体现了潮汕地区的审美情趣和文化传统。潮州木雕的传承对于研究中国传统木雕艺术具有重要意义。','陈培臣（国家级）、陈锡藩（省级）、林木龙（省级）等潮州木雕传承人',NULL,NULL,'[\"《潮州木雕》清·民间 刀下生花木作纸，雕出万象入画图。 潮州木雕甲天下，精细入微见真功。\"]','[\"清明\", \"谷雨\", \"立夏\", \"夏至\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:11'),(146,'端砚制作技艺','传统手工艺','砚石雕刻','宋代','广东','','适合文房四宝主题深度体验。','端砚产于广东肇庆，因唐宋时期属端州而得名。端砚始于唐代，有一千多年的历史，与歙砚、洮砚、澄泥砚并称中国四大名砚。端砚石质细腻温润，发墨如油，研出的墨汁细腻均匀，有\"群砚之首\"的美誉。','端砚是中国文房四宝之首，具有\"温润如玉、细腻发墨\"的特点。端砚石品丰富，有眼、青花、冰纹、金银线等天然纹理，是大自然鬼斧神工的杰作。端砚制作技艺涉及采石、选石、设计、雕刻、打磨等数十道工序，具有重要的工艺价值。','罗海（国家级）、程文（省级）、李锐文（省级）等端砚制作技艺传承人',NULL,NULL,'[\"《端砚》宋·苏辙 端溪千载韵悠悠，石品天成墨韵稠。 发墨不沾濡纸背，端州砚工第一流。\"]','[\"立冬\", \"小雪\", \"大雪\", \"冬至\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:11'),(147,'宋锦织造技艺','传统手工艺','宋锦织造','宋代','江苏','','适合宋代织造美学路线。','宋锦是中国传统的丝织品，因产于宋代且纹样独特而得名。宋锦色泽典雅，图案多为几何纹和植物纹，构图严谨，富有宋代美学特征。宋锦分为重锦、细锦、匣锦三大类，主要用于宫廷服饰和珍贵书画装裱。','宋锦是中国丝织工艺的杰出代表，被誉为\"锦绣之冠\"。宋锦织造技艺复杂，需由提花工和织手两人配合操作，织造速度极慢，一寸锦缎往往需要数日的功夫。宋锦的传承对于研究中国传统丝织技艺具有重要意义。','钱小萍（国家级）、朱艳（省级）等宋锦织造技艺传承人',NULL,NULL,'[\"《宋锦》宋·陆游 织金梭子出霞光，锦上添花韵味长。 宋韵千古传佳话，织女飞梭织梦香。\"]','[\"立秋\", \"白露\", \"秋分\", \"寒露\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:11'),(148,'京绣','传统手工艺','京派刺绣','清代','北京','','适合春节场景下体验京派刺绣纹样。','京绣又称\"宫绣\"或\"宫廷绣\"，是北京地区的传统刺绣技艺。京绣起源于辽代，在明清时期达到鼎盛，专为宫廷御用。京绣针法严谨，配色典雅，图案多为龙凤、祥云、花卉等宫廷纹样，绣品富丽堂皇，体现了皇家气派。','京绣是中国刺绣艺术中最高水平的代表，被誉为\"宫绣\"。京绣针法丰富多样，有平绣、套绣、乱绣、打籽绣等数十种针法。京绣作品题材庄严，多为龙凤呈祥、百花献瑞等吉祥图案，具有重要的艺术价值和文化价值。','孙颖（国家级）、刘秀梅（省级）、李静（省级）等京绣传承人',NULL,NULL,'[\"《京绣》清·民间 金丝银线绣龙袍，宫廷技艺领风骚。 京绣华美甲天下，非遗传承在今朝。\"]','[\"春节\", \"元宵节\", \"清明\", \"谷雨\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:11'),(149,'兔儿爷彩塑','传统手工艺','彩塑艺术','清代','北京','','适合老北京节庆民艺路线。','兔儿爷是北京的传统民间玩具，起源于明代，是北京中秋节令玩具。兔儿爷人身兔面，头戴金盔，身披战袍，威风凛凛。据传兔儿爷是嫦娥奔月后派到人间救苦救难的玉兔，受到人们的敬奉和喜爱。','兔儿爷是老北京中秋节文化的重要象征，承载着北京人的童年记忆和民俗情感。兔儿爷彩塑造型生动，色彩艳丽，是老北京民间工艺美术的代表作。兔儿爷的传承对于研究老北京民俗文化具有重要意义。','双起翔（兔儿爷传承人）、林永奎（兔儿爷传承人）等兔儿爷彩塑传承人',NULL,NULL,'[\"《兔儿爷》清·民间 兔儿爷来送吉祥，中秋拜月福满堂。 老北京的记忆，非遗技艺永流芳。\"]','[\"中秋\", \"白露\", \"秋分\", \"寒露\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:11'),(150,'京作剪纸','传统手工艺','剪纸艺术','唐代起源，明清鼎盛','北京市','national','京作剪纸，又称京派剪纸，是剪纸艺术中极具地域辨识度的流派，扎根北京这片兼具皇家气度与市井烟火的土地，历经千年沉淀，融合宫廷雅致与民间质朴，形成了独有的艺术风骨。它是流淌在老北京胡同里、镌刻在百姓生活中的文化基因。','京作剪纸起源于唐代，盛于明清时期，距今已有千年历史。明朝永乐年间，宫廷剪纸艺术家已达数百人，为宫廷庆典、祭祀活动提供剪纸装饰。清代，《红楼梦》中描述的贾府春节剪窗花场景，展现了剪纸艺术在当时贵族家庭的普及程度。近现代以来，京作剪纸历经沉浮，在战乱与变革中艰难传承，同时也在时代浪潮中不断创新，适应新的生活场景。','京作剪纸是北京市非物质文化遗产，承载的是一门手艺，是老北京人的生活智慧、审美情趣与家国情怀。它具有重要的历史、艺术和文化价值，为研究北京地区民俗文化、社会生活提供了重要依据。京作剪纸的保护和传承，对于弘扬中华优秀传统文化、增强文化自信具有重要意义。','张晓林（第三代传承人）、张立君（第四代传承人）','[\"http://te3ceeisz.hn-bkt.clouddn.com/heritage/images/fa9ef0c3-73ee-419b-b43e-c3b86cfc7a96.png\"]','http://te3ceeisz.hn-bkt.clouddn.com/heritage/videos/38d42d93-f554-47f2-a901-926dd1388099.mp4','[\"《京作剪纸》清·张晓林 金剪飞舞落红纸，京城故事入画图。 千年传承刀下生，非遗技艺永流芳。\"]','[\"春节\", \"元宵节\", \"清明\", \"端午节\"]',NULL,NULL,1,0,'2026-03-28 09:48:21','2026-04-28 11:08:49'),(151,'毛猴制作技艺','传统手工艺','毛猴制作','清代','北京','','适合串联京味民俗和手工体验。','毛猴是老北京的传统手工艺品，起源于清代道光年间。毛猴以蝉蜕和辛夷（玉兰花骨朵）为原料，经巧妙拼粘，塑造出各种人物和动物形象。毛猴制作技艺是北京独有的民间工艺，被誉为\"无言的戏，有声的画\"。','毛猴制作技艺是老北京民间艺术的独特创造，体现了北京人的智慧和幽默。毛猴作品题材广泛，有戏曲人物、市井生活、历史故事等，造型生动，妙趣横生。毛猴技艺的传承对于研究老北京民俗文化具有重要意义。','张增财（毛猴传承人）等毛猴制作技艺传承人',NULL,NULL,'[\"《毛猴》清·民间 蝉蜕辛夷巧拼粘，毛猴百态入眼帘。 老北京的记忆，非遗技艺代代传。\"]','[\"清明\", \"谷雨\", \"立夏\", \"夏至\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:11'),(152,'冰糖葫芦制作技艺','传统手工艺','糖艺小吃','清代','北京','','适合春节市集与街区体验。','冰糖葫芦是北京的传统小吃，起源于南宋时期。冰糖葫芦以山楂为主料，用竹签串成串，裹以糖稀制成。糖稀遇冷凝固，形成晶莹剔透的糖壳，酸甜可口，深受人们喜爱。冰糖葫芦是北京冬季最具代表性的街头小吃。','冰糖葫芦是老北京饮食文化的重要符号，承载着北京人的童年记忆。冰糖葫芦制作技艺简单却不简单，熬糖火候的掌握是关键。冰糖葫芦的传承对于研究老北京民俗文化具有重要意义。','张振华（冰糖葫芦传承人）、张全（冰糖葫芦传承人）等冰糖葫芦制作技艺传承人',NULL,NULL,'[\"《冰糖葫芦》清·民间 冰糖葫芦红彤彤，酸酸甜甜味道浓。 老北京的记忆，非遗小吃永流芳。\"]','[\"小雪\", \"大雪\", \"冬至\", \"立春\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:11'),(153,'苏扇制作技艺','传统手工艺','制扇工艺','宋代','江苏','','适合文人器物与手工体验路线。','苏扇是苏州地区的传统手工艺品，包括折扇、团扇、檀香扇等品种。苏扇以竹木为骨，绢绸为面，绘画题诗，极具江南文人雅趣。苏州制扇技艺精湛，有\"苏州扇子甲天下\"的美誉。','苏扇是江南文人文化的象征，体现了江南士人的审美情趣。苏扇制作涉及选材、削骨、裱面、绘画、题诗等多道工序，每道工序都有严格要求。苏扇承载着丰富的文化内涵，是研究江南文化的重要载体。','徐义林（国家级）、王健（省级）等苏扇制作技艺传承人',NULL,NULL,'[\"《苏扇》明·唐寅 苏州扇子世无双，竹骨绢面画端详。 一扇在手清风来，文人雅士共欣赏。\"]','[\"立夏\", \"小满\", \"芒种\", \"夏至\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:11'),(154,'缂丝织造技艺','传统手工艺','缂丝织造','宋代','江苏','','适合高阶织造工艺体验。','缂丝是中国最古老的丝织品种之一，起源于汉代，盛行于唐代。缂丝又称\"刻丝\"，以生蚕丝为经，彩色熟蚕丝为纬，采用\"通经断纬\"的技法织造。缂丝图案层次分明，色彩丰富，可以织出极其精细的图案，有\"织中之圣\"的美誉。','缂丝是中国丝织工艺的巅峰之作，被誉为\"织中圣品\"。缂丝织造技艺极其复杂，一件作品往往需要数月甚至数年才能完成。缂丝作品题材广泛，包括人物、山水、花鸟等，具有极高的艺术价值和收藏价值。','王嘉澍（国家级）、顾建东（省级）等缂丝织造技艺传承人',NULL,NULL,'[\"《缂丝》宋·佚名 通经断纬见精工，织出丹青夺天工。 千年缂丝传佳话，非遗技艺永流芳。\"]','[\"立秋\", \"白露\", \"秋分\", \"寒露\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:11'),(155,'绒花制作技艺','传统手工艺','绒花制作','清代','天津','','适合春节头饰和节庆花艺体验。','绒花是天津的传统手工艺品，起源于清代。绒花以蚕丝为原料，经染色、勾条、打尖、传花等数十道工序制成。绒花造型逼真，色彩艳丽，有花鸟虫鱼、人物造型等品种。绒花是天津民俗文化的重要组成部分。','绒花制作技艺是天津传统手工艺的杰出代表，体现了天津人民的审美情趣。绒花制作工序繁琐，每道工序都有严格要求。绒花作品寓意吉祥，有荣华富贵、幸福美满的寓意。绒花的传承对于研究天津民俗文化具有重要意义。','刘工艺（绒花传承人）等绒花制作技艺传承人',NULL,NULL,'[\"《绒花》清·民间 绒花开在指尖上，千姿百态斗芬芳。 非遗技艺代代传，绒花永伴福满堂。\"]','[\"春节\", \"元宵节\", \"清明\", \"端午节\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:11'),(156,'潍坊花灯制作技艺','传统手工艺','花灯扎制','清代','山东','','适合春节夜游和彩灯制作体验。','潍坊花灯历史悠久，起源于宋代，盛行于明清。潍坊花灯造型独特，有宫灯、动物灯、花卉灯、人物灯等数千个品种。潍坊花灯以竹木为骨架，丝绸、绢帛为灯罩，内燃蜡烛，色彩艳丽，形态逼真。','潍坊花灯是山东民俗文化的重要代表，体现了齐鲁人民的审美情趣。潍坊花灯制作涉及扎作、裱糊、彩绘、装饰等多道工序，每道工序都有严格要求。潍坊花灯寄托了人们对美好生活的向往，具有重要的民俗学研究价值。','张效公（国家级）、胡瑞（省级）等潍坊花灯制作技艺传承人',NULL,NULL,'[\"《花灯》宋·辛弃疾 东风夜放花千树，更吹落、星如雨。 宝马雕车香满路，凤箫声动，玉壶光转，一夜鱼龙舞。\"]','[\"元宵节\", \"春节\", \"中秋\", \"重阳节\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:11'),(157,'鲁绣','传统手工艺','齐鲁刺绣','清代','山东','','适合齐鲁针法与节庆纹样体验。','鲁绣是山东地区的传统刺绣技艺，起源于春秋时期，有两千多年的历史。鲁绣针法独特，以\"衣线绣\"著称，即用衣服的纱线进行刺绣。鲁绣图案粗犷豪放，色彩浓烈，富有齐鲁大地的质朴风情。','鲁绣是中国刺绣艺术的重要流派之一，具有图案豪放、色彩浓烈、针法独特的风格。鲁绣作品题材广泛，有花鸟虫鱼、人物山水、吉祥图案等。鲁绣的传承对于研究齐鲁文化和北方刺绣艺术具有重要意义。','徐秀娟（国家级）、宋爱华（省级）等鲁绣传承人',NULL,NULL,'[\"《鲁绣》清·民间 齐鲁大地绣春风，针线飞舞织彩虹。 鲁绣豪放甲天下，非遗技艺永流芳。\"]','[\"春分\", \"清明\", \"谷雨\", \"立夏\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:11'),(158,'龙舟习俗','传统民俗','龙舟竞渡','宋代','广东','','适合端午主题民俗路线。','龙舟竞渡起源于春秋战国时期，相传是为纪念爱国诗人屈原。龙舟习俗在南方地区广泛流传，尤以广东、福建、广西等地最为盛行。每年端午节，各地举行龙舟竞渡活动，热闹非凡。龙舟制作工艺精湛，船身细长，饰以龙鳞。','龙舟习俗是中国传统民俗文化的重要组成部分，承载着中华民族的爱国情怀。龙舟竞渡体现了团结协作、奋勇拼搏的精神。龙舟制作涉及选木、凿船、彩绘等多道工序，具有重要的工艺价值和文化价值。','苏大广（龙舟习俗传承人）、梁国添（龙舟习俗传承人）等龙舟习俗传承人',NULL,NULL,'[\"《端午竞渡》唐·张建封 鼓声三下红旗开，两龙跃出浮水来。 棹影斡波飞万剑，鼓声劈浪鸣千雷。\"]','[\"端午节\", \"夏至\", \"小暑\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:22'),(159,'寒食清明踏青习俗','传统民俗','踏青习俗','宋代','江苏','','适合清明踏青和春日出游路线。','寒食清明踏青是中国传统的春游习俗，距今已有两千多年的历史。寒食节在清明前一二日，源于介子推的故事。清明时节，春暖花开，人们外出踏青赏春，祭祖扫墓。踏青习俗延续至今，成为中华民族的重要传统。','寒食清明踏青习俗是中华民族的重要传统，融合了寒食文化、祭祀文化和春游文化。这一习俗体现了中华民族慎终追远、珍惜春光的精神追求。踏青习俗对于研究中国传统民俗文化具有重要意义。','李更（寒食清明踏青习俗传承人）等寒食清明踏青习俗传承人',NULL,NULL,'[\"《清明》唐·杜牧 清明时节雨纷纷，路上行人欲断魂。 借问酒家何处有，牧童遥指杏花村。\"]','[\"清明\", \"春分\", \"谷雨\", \"立夏\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:11'),(160,'香包佩饰习俗','传统民俗','香包佩饰','清代','安徽','','适合端午主题的民俗体验。','香包又称香囊、香袋，是中国的传统手工艺品和佩饰。香包以丝绸布料缝制，内装香料，有驱蚊避邪、祈福纳祥的寓意。香包佩饰习俗在端午节最为盛行，人们佩戴香包以祈求平安健康。香包造型精美，色彩艳丽。','香包佩饰习俗是中国传统民俗文化的重要组成部分，体现了中华民族的审美情趣和对美好生活的向往。香包制作涉及裁剪、缝制、填料、装饰等多道工序，每道工序都有严格要求。香包的传承对于研究中国传统民俗文化具有重要意义。','张仙红（省级）、李彩红（省级）等香包佩饰习俗传承人',NULL,NULL,'[\"《香包》宋·陆游 端午佩香包，艾草驱邪好。 彩丝系玉腕，福寿永相保。\"]','[\"端午节\", \"夏至\", \"小暑\"]',NULL,NULL,0,0,'2026-03-28 09:48:21','2026-04-28 10:45:11'),(176,'汝瓷','传统技艺','青瓷烧制技艺','始于唐代中期，盛于北宋中晚期','河南省汝州市、宝丰县','national','汝瓷是中国宋代\"五大名窑\"之首，因位于宋代汝州而得名。汝瓷以天青色釉为主，釉色温润如玉，素雅含蓄，体现了宋代清淡优雅的审美追求。汝瓷烧制技艺技术性强，采用一钵一器支钉托烧的叠烧技法，具有配料绝、变色绝、裂纹绝、应光绝四大特色。','汝瓷烧制技艺始于唐代中叶，北宋中晚期达到鼎盛时期，为北宋宫廷专造。汝官窑存续时间只有20年左右，成品率极低，传世作品不足百件。宋、金对峙时期，汝官窑停烧，烧制技艺传至民间。元、明、清至当代，汝瓷烧制技艺在民间传承、延续、发展。新中国成立后，20世纪80年代天青釉汝瓷复烧成功。2011年5月23日，汝瓷烧制技艺经国务院批准列入第三批国家级非物质文化遗产名录。','汝瓷烧制技艺具有重要的历史、艺术和科学价值。历史上汝窑所烧精品均为皇家御用品，蕴涵唐宋的文化艺术精神，结晶着唐宋的科技水平与能力。汝瓷独特的釉色对后世瓷器烧造产生了深远影响，至今一直被视作瓷釉的楷模而被仿烧。汝瓷烧制技艺的传承延续着口传心授的方式，为传统工艺的传承提供了重要借鉴价值。','朱文立、李廷怀、孟玉松、王君子等国家级传承人','[\"http://te3ceeisz.hn-bkt.clouddn.com/heritage/images/aa2ceab3-f65f-413e-8591-4d97b156f352.png\"]','http://te3ceeisz.hn-bkt.clouddn.com/heritage/videos/1ef2941a-ebc8-46c8-8917-c8752849fe57.mp4','[\"《汝瓷》宋·欧阳修 汝窑出天青，千峰翠色凝。 温润如君子，冰裂纹中情。\"]','[\"立夏\", \"小满\", \"芒种\", \"夏至\", \"大暑\"]',NULL,NULL,1,0,'2026-03-30 11:46:15','2026-04-28 11:09:47'),(177,'傩舞','传统舞蹈','祭祀舞蹈','原始社会','江西、安徽、贵州、云南、广东、广西、四川等省份','national','傩舞又称鬼戏，是中国汉族最古老的一种驱鬼敬神、驱瘟避疫的娱神祭祀舞蹈，起源于汉族先民的自然崇拜、图腾崇拜和巫术意识，在原始社会氏族部落形成初期便诞生。','傩舞起源于原始社会，周代时纳入国家礼制。先秦文献记载，傩礼是希望调理四时阴阳，以求寒暑相宜，风调雨顺，五谷丰登，人畜平安，国富民生。唐宋以后，儒学地位的提高压制了傩文化的传播，于是傩文化重心开始转移到西南边远等蛮荒之地。时至今日，傩舞已经由娱神的祭祀活动，衍变为娱神与娱人相结合的民俗活动。2006年5月20日，傩舞经国务院批准列入第一批国家级非物质文化遗产名录。','傩舞是中国舞蹈\"活化石\"，是历史、民俗、民间宗教和原始戏剧的综合体，蕴藏着丰富的文化基因，具有重要的研究价值。傩文化代代相传沿袭至今，是中华民族文化特点鲜明的民俗活动，在经济文化、道德教化、以及社交娱乐等方面发挥着正能量。','罗会武','[\"http://te3ceeisz.hn-bkt.clouddn.com/heritage/images/e39addc3-9554-4c77-8339-8dbc5a62f1a2.png\"]','http://te3ceeisz.hn-bkt.clouddn.com/heritage/videos/32233442-f934-4b9a-9ea9-6891339d500b.mp4','[\"《傩舞》宋·苏辙 驱傩逐疫古风存，面具狰狞惊鬼神。 舞步铿锵震天地，祈福纳祥保平安。\"]','[\"春节\", \"元宵节\", \"清明\", \"重阳节\"]',NULL,NULL,1,0,'2026-03-30 14:04:59','2026-04-28 11:10:17'),(178,'敦煌壁画','传统美术','彩绘壁画','北魏至元代','甘肃省敦煌市','national','敦煌壁画是敦煌莫高窟艺术的重要组成部分，是中国古代壁画艺术的巅峰之作。壁画内容丰富，包括佛像画、经变画、故事画、山水画等，展现了1000多年间中国绘画艺术的发展历程和辉煌成就。','敦煌壁画始于北魏时期，历经西魏、北周、隋、唐、五代、宋、西夏、元等朝代，延续1000多年。唐代是敦煌壁画的鼎盛时期，壁画艺术达到了前所未有的高度。1900年莫高窟藏经洞被发现后，敦煌壁画闻名世界。','敦煌壁画是丝绸之路上东西方文化交融的结晶，具有极高的历史、艺术和科学价值。壁画中保存了大量珍贵的历史资料，为研究中国古代社会、宗教、艺术、文化提供了重要依据。敦煌壁画的保护和研究，对于传承中华优秀传统文化、促进文化交流具有重要意义。','樊锦诗','[\"http://te3ceeisz.hn-bkt.clouddn.com/heritage/images/4cc3e538-b70d-42bc-905a-1b71ba8ba1d0.png\"]','http://te3ceeisz.hn-bkt.clouddn.com/heritage/videos/d4da8c10-b2bd-4880-9b26-a6ac96364aa1.mp4','[\"《敦煌壁画》唐·王维 大漠孤烟直，长河落日圆。 莫高窟中画，千年壁影寒。\"]','[\"清明\", \"谷雨\", \"立夏\", \"夏至\"]',NULL,NULL,1,0,'2026-03-30 14:20:57','2026-04-28 11:10:45'),(179,'皮影戏','传统戏剧','操纵影偶表演','起源于汉代，形成于唐末五代，盛于清代','全国各省份（河北唐山、陕西华县、甘肃环县、山西孝义、浙江海宁、湖北江汉平原、广东陆丰、辽宁凌源等）','national','皮影戏又称\"影子戏\"或\"灯影戏\"，是中华民族最古老的民间艺术形式之一。皮影戏是一种用兽皮或纸板剪制形象并借灯光照射所剪形象而表演故事的戏曲形式，是集绘画、雕刻、音乐、演唱为一体的综合性民间艺术，被誉为\"电影的鼻祖\"\"最早的卡通动画\"。','皮影戏从有文字记载已经有2000多年的历史。汉代已有\"弄影\"的记载，唐代开始发展，宋代已经成熟并盛行，经过宋、金、元、明四个历史时期的发展，在清代呈现出繁荣局面。元代时期传至西亚和欧洲。2006年5月20日，经国务院批准列入第一批国家级非物质文化遗产名录。2011年，中国皮影戏入选人类非物质文化遗产代表作名录。','皮影戏是我国重要的民间传统艺术，具有重要的历史、艺术和文化价值。皮影戏的传承延续着口传心授的方式，为文化传承的方式方法提供了重要借鉴价值。皮影戏的唱腔、音乐、表演、造型有着本地域特有的风格，受到国内外同行和观众的赞誉，具有很高的欣赏与研究价值。皮影戏是中华民族艺术殿堂里的一颗璀璨明珠，更是让当代人触摸历史脉搏、留住文化记忆的重要载体。','许子林（凌源皮影戏）、张国治（唐山皮影戏）、汪天喜（华县皮影戏）等50位国家级传承人','[\"http://te3ceeisz.hn-bkt.clouddn.com/heritage/images/24b312dc-4f1d-43ce-9474-94a3842084d4.png\"]','http://te3ceeisz.hn-bkt.clouddn.com/heritage/videos/11abc521-76b6-4689-89bc-c0b27724e6d2.mp4','[\"《皮影戏》清·纪晓岚 三尺生绡作戏台，全凭十指逞诙谐。 有时明镜青灯下，一片明霞入梦来。\"]','[\"春节\", \"元宵节\", \"清明\", \"谷雨\", \"夏至\"]',NULL,NULL,1,0,'2026-03-30 14:30:53','2026-04-28 11:11:09'),(180,'京剧','传统戏剧','中国国剧','形成于清代（1790年徽班进京）','北京（全国各省份均有分布）','national','京剧被称为\"国剧\"、誉为\"国粹\"，是中国戏曲的集大成者，蕴含着中华历史文化的深厚底蕴。京剧是在徽汉合流的基础上，融合了徽调二黄与汉调西皮，经过200多年的发展形成的综合性舞台艺术，是中国第一大剧种。','京剧起源于清代，1790年（乾隆五十五年）为给乾隆皇帝祝寿，扬州盐商组织\"三庆\"徽班进京，徽班进京演出拉开帷幕。此后，其他徽班也相继入京，形成了著名的\"三庆\"\"四喜\"\"春台\"\"和春\"四大徽班。道光年间，汉调艺人进京加入徽班演出，形成了\"徽汉合流\"的局面，京剧由此诞生。2010年11月16日，京剧被联合国教科文组织列入\"人类非物质文化遗产代表作名录\"。','京剧作为中国文化的瑰宝，对于构建中华民族的精神家园有着不可替代的作用。京剧的传承延续着科班体系、家族血脉、师徒门户的活态传承网络，为文化传承提供了重要借鉴价值。京剧的唱腔、表演、脸谱、服饰等具有独特的艺术价值，受到国内外观众的喜爱，具有很高的欣赏与研究价值。京剧是中华民族艺术殿堂里的一颗璀璨明珠，更是让当代人触摸历史脉搏、留住文化记忆的重要载体。','梅葆玖（梅派）、谭元寿（谭派）、张火丁（程派）、李胜素（梅派）、孟广禄（裘派）、王珮瑜（余派）等国家级传承人','[\"http://te3ceeisz.hn-bkt.clouddn.com/heritage/images/af468a89-dc77-4e51-9f62-89365b7dfd7a.png\"]','http://te3ceeisz.hn-bkt.clouddn.com/heritage/videos/f86e6205-7f23-453d-9cc0-2eab32e8f223.mp4','[\"《京剧》清·爱新觉罗·弘历 徽调汉调聚京城，梨园子弟竞纷呈。 生旦净丑皆成戏，唱念做打见真情。\"]','[\"立春\", \"雨水\", \"惊蛰\", \"春分\", \"清明\"]',NULL,NULL,1,0,'2026-03-30 14:38:38','2026-04-28 11:11:47');
