INSERT INTO `merchant_reviews` VALUES (1,10011,10000,NULL,1,'activity',4.0,'nice','2026-03-31 08:42:35','2026-03-31 08:42:35'),(2,10011,10000,NULL,14,'activity',5.0,'非常有意义','2026-04-05 20:12:42','2026-04-05 20:12:42'),(3,10048,10000,NULL,NULL,'activity',5.0,'讲解特别细，木刻、上墨和揭纸的步骤都能跟得上，新手也不会慌。','2026-04-24 21:15:00','2026-04-24 21:15:00'),(4,10048,10020,NULL,NULL,'activity',4.5,'活动节奏舒服，材料准备很齐，最后做出来的成品很出片。','2026-04-24 21:15:00','2026-04-24 21:15:00'),(5,10048,10023,NULL,NULL,'activity',4.5,'空间布置很好看，老师也很耐心，适合朋友一起过来体验。','2026-04-24 21:15:00','2026-04-24 21:15:00'),(6,10025,10007,NULL,20,'activity',4.0,'《京剧脸谱沉浸体验》体验感很完整，老师讲解清楚，结束后对这门工艺更有兴趣了。','2026-04-27 10:00:00','2026-04-27 10:00:00'),(7,10025,10011,NULL,21,'activity',5.0,'《景泰蓝掐丝点蓝工坊》从勾线到上色都很顺，做完之后成就感很强，也很出片。','2026-04-27 10:00:00','2026-04-27 10:00:00'),(8,10025,10020,NULL,22,'activity',4.0,'《庙会面塑亲子课程》体验感很完整，老师讲解清楚，结束后对这门工艺更有兴趣了。','2026-04-27 10:00:00','2026-04-27 10:00:00'),(9,10025,10023,NULL,23,'activity',4.5,'《中轴灯彩夜游手作课》现场氛围很足，讲解和互动结合得很好，适合边看边体验。','2026-04-27 10:00:00','2026-04-27 10:00:00'),(10,10025,10025,NULL,24,'activity',4.5,'《清明风筝彩绘体验》从勾线到上色都很顺，做完之后成就感很强，也很出片。','2026-04-27 10:00:00','2026-04-27 10:00:00'),(11,10025,10026,NULL,25,'activity',4.0,'《京绣节庆纹样体验》把针法、纹样和节奏讲得很明白，跟着做很容易进入状态。','2026-04-27 10:00:00','2026-04-27 10:00:00'),(12,10025,10027,NULL,26,'activity',5.0,'《兔儿爷彩塑手作课》从勾线到上色都很顺，做完之后成就感很强，也很出片。','2026-04-27 10:00:00','2026-04-27 10:00:00'),(13,10025,10028,NULL,27,'activity',4.5,'《京作剪纸窗花体验》体验感很完整，老师讲解清楚，结束后对这门工艺更有兴趣了。','2026-04-27 10:00:00','2026-04-27 10:00:00'),(14,10025,10029,NULL,28,'activity',4.0,'《毛猴造景手作课》体验感很完整，老师讲解清楚，结束后对这门工艺更有兴趣了。','2026-04-27 10:00:00','2026-04-27 10:00:00'),(15,10025,10030,NULL,29,'activity',5.0,'《冰糖葫芦熬糖体验》体验感很完整，老师讲解清楚，结束后对这门工艺更有兴趣了。','2026-04-27 10:00:00','2026-04-27 10:00:00'),(16,10026,10031,NULL,30,'activity',4.5,'《苏绣针法体验课》把针法、纹样和节奏讲得很明白，跟着做很容易进入状态。','2026-04-27 10:00:00','2026-04-27 10:00:00'),(17,10026,10032,NULL,31,'activity',4.0,'《昆山腔身段体验》现场氛围很足，讲解和互动结合得很好，适合边看边体验。','20