INSERT INTO `travel_posts` VALUES (2,10011,'福建游神——中式信仰美学','曾以为神明住在云端\n直到走入福建的旧街巷\n迎上这场盛大的流动——\n原来最深的信仰\n就落在人间烟火里\n-\n当鼓点从青石板路深处传来\n神将巍峨的身姿转过巷角\n华服璀璨，眉目庄严\n却又带着一丝“人间气”——\n会接过孩童手中的糖果\n会为长者的祈福微微颔首\n那一刻突然懂得：\n所谓信仰\n不是高高在上的仰望\n而是人与神之间\n这份无声却厚重的连接\n-\n福州游神主要集中在长乐区，从正月初一开始到二月中，几乎每天都有，我追的这场是规模zui大的厚福游神：\n📍福州市长乐区潭头镇厚福乡\n📆正月初十、正月二十六\n⏰08:00-次日凌晨','normal','民俗节气','passed',NULL,'[\"http://te3ceeisz.hn-bkt.clouddn.com/posts/2/1.jpg\", \"http://te3ceeisz.hn-bkt.clouddn.com/posts/2/2.jpg\", \"http://te3ceeisz.hn-bkt.clouddn.com/posts/2/3.jpg\"]','[\"民俗节气\",\"非遗追年地图\",\"旅行中的非遗体验\",\"游神\",\"福建游神\",\"民俗\",\"新年\",\"春节\"]','public',1,8,0,'2026-03-28 19:49:45','2026-04-28 04:39:10',0,0,'zh','normal',NULL,NULL,0),(3,10011,'老祖宗肩上的“时尚单品” 火了上千年','一抹云霞落肩头，流转千年仍惊艳！\n云肩是中华民族服饰文化中历史悠久且独特的服饰瑰宝，既是古人“天人合一”的智慧凝结，更是东方美学的精神传承！\n云肩之美，在其极致工艺！\n✅ 形制考究：四合如意、柳叶式、八方云纹…每一片云肩的剪裁都暗含深意。四合如意象征“四方祥和”，柳叶式放射状纹样寓意“生命长青”，而八片垂云则对应传统节庆的平安祈愿 。\n✅ 纹样密码：石榴葡萄喻多子，蝙蝠葫芦兆福禄…云肩的刺绣每一针都承载着古人对生活的美好期许。\n✅ 工艺巅峰：立体剪裁贴合女子肩颈曲线，云肩针法竟有滚针、盘金等诸多针法，绣娘以线为笔，将四季花鸟、祥云瑞兽化作肩头画卷。\n传承与创新：让云肩走进日常\n如今，云肩不再只是博物馆的展品：中式婚纱、马面裙+云肩、毕业季学士服+云肩、巴黎奥运会体操服装等，现代日常服饰不断融入云肩这一传统元素，诠释出更多新中式可能。（图1-10源于大英博物馆；图11-17源于郑州博物馆）\n\n老祖宗肩上的“时尚单品” 火了上千年\n\n中国传统工艺振兴服务平台\n2025-04-21\n3292\n\n🪡八位掌灯人｜穿越千年女性非遗技艺图鉴\n\n元气小葫要早睡💤\n2025-12-17\n1198\n\n《探索100种东方美学》——㉙云肩\n\n言小柒MiaoMiao\n2025-07-15\n1840\n\n\n原味栗子（接稿版）\n2025-12-30\n1581\n\n时尚中国，非遗的fashion之路㈧\n\nShine耀\n2024-12-23\n7.9万\n\n一眼心动！藏在肩上的东方绝美“天空”✨\n\n云山有趣的非遗\n2025-12-06\n2.5万\n大家都在搜\n\n非遗文化服装\n\n中国十大非遗\n\n非遗服饰有哪些\n\n非遗拟人化绘画\n\nTHE SEA LIFE×傣锦：将热带生态景象织在身上\n\n非遗Plus\n2025-07-31\n547\n\n「锦序东方」服装效果图分享\n\n钰榕设计（约稿中）\n01-28\n199\n\n聆听传统美学｜非遗醒狮\n\n你说天空很美丽\n01-14\n233\n\n这不是国外大牌高定！\n\n毛豆\n2025-12-12\n3.6万\n\n一刀一剪一世界——带你领略非遗的魅力(02)\n\nAIGC杨太医\n2025-08-01\n703\n\n服设系列—非遗\n\n张小花花老师\n2025-03-24\n1057\n\n非遗服饰服装分层设计图\n\n漓月\n2025-12-12\n14\n\n🔥中国国际时装周｜非遗服饰文化惊艳秀场\n\n遗韵云游\n2025-12-09\n144\n\n把非遗绒花穿身上，那该有多美？\n\n宁心如\n02-13\n11.4万\n大家都在搜\n\n中国传统非遗服装\n\n非遗人物绘画素材\n\n非遗服饰图片\n\n非遗文化主题衣服\n\n广艺/毕业设计/把非遗穿身上\n\n一只小馒头\n2025-04-11\n2106\n发现\n直播\n发布\n通知\n我\n×\n拖拽到此处\n图片将完成下载\n由Fitkun图片批量下载提供\n\n中国传统工艺振兴服务平台\n关注\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n1/17\n老祖宗肩上的“时尚单品” 火了上千年\n一抹云霞落肩头，流转千年仍惊艳！\n云肩是中华民族服饰文化中历史悠久且独特的服饰瑰宝，既是古人“天人合一”的智慧凝结，更是东方美学的精神传承！\n云肩之美，在其极致工艺！\n✅ 形制考究：四合如意、柳叶式、八方云纹…每一片云肩的剪裁都暗含深意。四合如意象征“四方祥和”，柳叶式放射状纹样寓意“生命长青”，而八片垂云则对应传统节庆的平安祈愿 。\n✅ 纹样密码：石榴葡萄喻多子，蝙蝠葫芦兆福禄…云肩的刺绣每一针都承载着古人对生活的美好期许。\n✅ 工艺巅峰：立体剪裁贴合女子肩颈曲线，云肩针法竟有滚针、盘金等诸多针法，绣娘以线为笔，将四季花鸟、祥云瑞兽化作肩头画卷。\n传承与创新：让云肩走进日常\n如今，云肩不再只是博物馆的展品：中式婚纱、马面裙+云肩、毕业季学士服+云肩、巴黎奥运会体操服装等，现代日常服饰不断融入云肩这一传统元素，诠释出更多新中式可能。\n\n你喜欢什么样的云肩造型呢？评论区留言~','normal','服饰妆造','passed',NULL,'[\"http://te3ceeisz.hn-bkt.clouddn.com/posts/3/1.jpg\", \"http://te3ceeisz.hn-bkt.clouddn.com/posts/3/2.png\"]','[\"服饰妆造\",\"非遗\",\"东方美学\",\"云肩\",\"大英博物馆\",\"郑州博物馆\",\"传统服饰\"]','public',1,3,0,'2026-03-28 19:53:18','2026-04-28 04:39:10',0,0,'zh','normal',NULL,NULL,0),(4,10011,'唐三彩','釉色承千年，匠心照古今——洛阳唐三彩的非遗传承与时代新生\n在中华文明的璀璨星河中，洛阳唐三彩是一颗独特的星辰。它诞生于盛唐的沃土，以绚烂釉色、恢弘气势，成为那个时代的文化图腾；它历经千年岁月洗礼，在传承与创新的交织中，依然焕发着蓬勃生机，成为连接古今的文化桥梁。\n缘起盛唐：时代风骨孕育的艺术瑰宝\n唐三彩的诞生，是历史的必然。盛唐时期，洛阳作为十三朝古都，既是政治经济中心，也是丝绸之路的东方枢纽。东西方文化在此碰撞交融，为艺术创作注入了多元灵感\n工匠们以细腻的高岭土为胎，以金属氧化物为着色剂，经“制胎—施釉—烧制”三道核心工序，在窑火中完成一场“色彩的魔术”。不同于传统陶瓷的单一釉色，唐三彩的釉料在高温下自由流淌，红如丹砂、绿似翡翠、黄若蜜蜡，交融处形成的“流釉”效果，如云雾缭绕、如霞光漫卷，尽显盛唐的豪迈与浪漫。\n从皇室贵族的陪葬重器，到文人雅士的赏玩之物，唐三彩的题材无一不展现着盛唐的社会风貌与精神气度。它不仅是陶瓷艺术的巅峰，更是大唐盛世的“立体史书”。\n守正创新：非遗传承人的“破局”之路\n时光流转，盛唐落幕，但唐三彩的窑火并未熄灭。然而，在现代工业的冲击下，这门古老技艺曾一度面临“无人传承、无人问津”的困境。直到一批非遗传承人的出现，用“守正”筑牢根基，用“创新”开拓未来。\n“守正”是对古法工艺的敬畏。传承人李松茂坚守“手工制胎、手工施釉、柴窑烧制”的传统，每一件作品都要经过数十道工序，从陶土筛选到釉料调配，从入窑温度到烧制时间，都严格遵循古法。“柴窑的火性是电窑替代不了的，只有这样，才能烧出唐三彩独有的温润质感。”李松茂的话，道出了匠人的坚守。\n“创新”是与时代的对话。年轻传承人将唐三彩的经典元素与现代审美结合，推出了一系列文创产品：将三彩马做成小巧玲珑的车载摆件，把釉色纹样印在笔记本上甚至开发出“唐三彩DIY体验套装”，让消费者亲手感受施釉的乐趣。\n文化出海：千年釉色讲述中国故事\n如今，洛阳唐三彩已不再是中国的“文化瑰宝”，更成为世界了解中国的“文化名片”。在海外展出时，唐三彩马的矫健、乐伎俑的灵动，让外国观众惊艳于中国古代艺术的魅力；非遗传承人带着技艺走出国门，让世界看见中国匠心。\n从盛唐的窑火到如今的国际舞台，从博物馆的陈列品到日常的文创产品，洛阳唐三彩的传承之路是中国非遗文化发展的缩影。它用绚烂的釉色，诉说着中华文明的博大精深；用不变的匠心，诠释着文化传承的力量。','normal','美术造物','passed',NULL,'[\"http://te3ceeisz.hn-bkt.clouddn.com/posts/4/1.png\", \"http://te3ceeisz.hn-bkt.clouddn.com/posts/4/2.jpg\", \"http://te3ceeisz.hn-bkt.clouddn.com/posts/4/3.jpg\"]','[\"美术造物\"]','public',1,10,0,'2026-03-28 19:58:05','2026-04-28 04:39:10',0,0,'zh','normal',NULL,NULL,0),(5,10011,'傩戏|中国硬核非遗','傩戏起源于商周时期的驱傩仪式，最初是古人通过歌舞祭祀驱鬼逐疫、祈福纳吉的宗教活动。汉代后逐渐融入娱人成分，宋代受民间歌舞影响发展为傩戏，元代至明清时期与地方戏曲融合，形成多样化流派。其历史可追溯至先秦的巫歌傩舞，被誉为“中国戏剧活化石”。\n	\n表演形式\n面具文化：演员佩戴木质或丝质面具（称“脸子”），造型夸张狰狞，直观区分角色性格，如贵州德江傩戏的面具多达上百种。\n宗教仪式融合：演出分“开坛”“开洞”“闭坛”三阶段，与祭祀活动一体，如湖北恩施傩戏需杀鸡请神、烧纸祭祖。\n傩技绝活：包含喷火、上刀梯、过火海等惊险技艺，体现原始巫术色彩。\n	\n音乐与剧目\n音乐以打击乐为主（锣、鼓、钹），辅以山歌、佛道乐曲，唱腔粗犷，多采用一唱众和形式。\n	\n剧目分三类：\n正戏：如《仙姑送子》《发五猖》，宗教色彩浓厚；\n傩堂小戏：如《采香》《陈州放粮》，娱乐性强；\n外台戏：吸收民间故事的《孟姜女》《三国演义》等。\n	\n傩戏主要分布于西南及长江流域，因地域文化差异形成多种流派：\n1.恩施傩戏（湖北）：分“傩愿戏”与“坛傩”，前者融入花鼓戏技巧，后者保留明代祭祖仪式，面具制作工艺独特。\n2.池州傩戏（安徽）：以宗族为单位演出，每年春秋两祭，保留《刘文龙》等古剧目，被誉为“无傩不成村”。\n3.侗族傩戏“咚咚推”（湖南）：舞蹈以“三角形”步伐模拟耕牛动作，剧目融合侗族生活与三国故事。\n4.德江傩堂戏（贵州）：被称为“中国戏剧活化石”，完整保留汉代傩仪传统，表演包含复杂法事。\n5.武安傩戏（河北）：具宋代宫廷傩遗风，角色“掌竹”为宋金杂剧引戏人遗存。','normal','戏曲演绎','passed',NULL,'[\"http://te3ceeisz.hn-bkt.clouddn.com/posts/5/1.jpg\", \"http://te3ceeisz.hn-bkt.clouddn.com/posts/5/2.jpg\"]','[\"非遗\",\"傩戏\",\"非物质文化遗产\",\"非遗传承\",\"传统文化\",\"恩施傩戏\",\"池州傩戏\",\"戏曲演绎\",\"美术造物\"]','public',1,6,0,'2026-03-28 20:01:41','2026-04-28 04:39:10',0,0,'zh','normal',NULL,NULL,0),(6,10011,'以针为笔，以丝为墨，绣出江南的呼吸','苏绣，源于江苏苏州一带，以其独特的艺术魅力和精湛技艺位居“四大名绣”之首，素有“精、细、雅、洁”之称，并于2006年入选国家级非物质文化遗产。\n艺术特色：\n苏绣的灵魂在于“平、齐、细、密、匀、顺、和、光”八字。其最显著的特点是 “精微雅致” 。绣工们常将一根头发丝般粗细的丝线劈成更细的1/16甚至1/32来进行创作，使作品达到“不见针线痕迹，只觉画面生动”的境界。\n代表技艺：\n双面绣是苏绣皇冠上的明珠。绣娘们在同一块底料上，一次施针，正反两面却呈现出构图完整、针法相同而画面可能不同的完美图案，令人拍案叫绝。代表作《猫》更是将这一技艺发挥到极致，丝线天然的光泽将小猫蓬松的毛发、灵动的眼神表现得栩栩如生。\n文化内涵：\n苏绣深受吴地文化的熏陶，作品题材多取自江南文人画，充满诗情画意。它不仅是技艺的展现，更是江南水乡温婉、灵动、典雅气质的集中体现，是流动在指尖上的姑苏风情。','normal','织物手工','passed',NULL,'[\"http://te3ceeisz.hn-bkt.clouddn.com/posts/6/1.jpg\", \"http://te3ceeisz.hn-bkt.clouddn.com/posts/6/2.jpg\", \"http://te3ceeisz.hn-bkt.clouddn.com/posts/6/3.jpg\"]','[\"织物手工\",\"非遗文化\",\"苏绣\",\"刺绣\"]','public',1,15,0,'2026-03-28 20:04:27','2026-04-28 04:39:10',0,0,'zh','normal',NULL,NULL,0),(7,10011,'认识一个非物质文化遗产——苗绣','⭐️起源\n贵州苗绣，一部用针线书写的民族史诗。苗绣起源可回溯到上古时期，与古代濮人的雕题文身有着千丝万缕的联系。彼时，随着濮人后裔南蛮掌握蚕桑技术，雕题文身逐渐演变为“描” ，待骨针、铜针出现，挑花和织花工艺应运而生。战国时期，苗绣正式在苗族服饰上崭露头角。\n元明清时期，因各支系苗民以不同动物为图腾，苗绣纹样风格各异，氏族间的交流又促使苗绣不断融合发展。\n2006年5月20日，贵州苗绣被列为国家级非物质文化遗产，遗产编号为Ⅶ-22。近年来，不断创新，融入现代设计与时尚产业，在国际舞台大放异彩，实现传承与发展的新跨越 。\n⭐️价值\n苗族没有传统意义上的文字，苗绣充当了“史书”角色。绣品中大量的神话传说、英雄故事、迁徙历程等图案，记录着苗族起源、发展轨迹，承载民族记忆与文化基因，像蝴蝶妈妈传说绣样，展现苗族独特创世观。\n此外，苗绣针法极为丰富，有平绣、辫绣、缠绣等几十种，每种针法呈现不同肌理质感 。色彩搭配大胆热烈，多运用红、黄、蓝等对比强烈的原色，形成鲜明视觉冲击，几何纹、动植物纹等图案造型夸张抽象，充满想象力与艺术感染力，具有极高的艺术价值。','normal','织物手工','passed',NULL,'[\"http://te3ceeisz.hn-bkt.clouddn.com/posts/7/1.png\", \"http://te3ceeisz.hn-bkt.clouddn.com/posts/7/2.png\"]','[\"织物手工\",\"苗绣\"]','public',1,10,0,'2026-03-28 22:33:59','2026-04-28 04:39:10',0,0,'zh','normal',NULL,NULL,0),(8,10000,'abc','The title and body have no clear topic. The text looks like random fragments with no useful information or readable value.','normal','other','rejected','Low quality and insufficient information','[]','[\"meaningless\",\"low_quality\",\"rejected\"]','public',1,4,0,'2026-03-29 14:07:51','2026-04-27 21:20:14',0,0,'en','normal',NULL,NULL,0),(10,10047,'加我wx','This post directly asks readers to add a contact account and contains obvious off-platform promotion and marketing intent.','normal','other','rejected','Contains contact info and promotional intent','[\"https://travelate.oss-cn-wuhan-lr.aliyuncs.com/yayfolk/posts/10/1.jpg\"]','[\"contact\",\"promotion\",\"marketing\"]','public',1,0,0,'2026-03-29 14:57:27','2026-04-27 21:20:14',0,0,'en','normal',NULL,NULL,0),(11,10047,'毒品','This post contains prohibited sensitive terms and inappropriate implications, creating a clear moderation risk.','normal','other','rejected','Contains prohibited sensitive words','[\"https://travelate.oss-cn-wuhan-lr.aliyuncs.com/yayfolk/posts/11/1.webp\",\"https://travelate.oss-cn-wuhan-lr.aliyuncs.com/yayfolk/posts/11/2.webp\"]','[\"sensitive\",\"prohibited\",\"rejected\"]','public',1,2,0,'2026-03-29 15:02:26','2026-04-27 21:20:14',0,0,'en','normal',NULL,NULL,0),(12,10011,'非遗珍宝｜点翠：千年不褪色的蓝','点翠，一项被誉为“首饰工艺绝唱”的国家级非物质文化遗产，以翠羽为墨，金银为骨，在方寸之间勾勒出千年不褪的华彩。它曾是帝王凤冠上的璀璨星辰，如今虽渐隐于时光，却仍是东方美学中一抹无法复制的幽蓝梦境。\n✨ 精工细作，巧夺天工\n点翠工艺的极致，在于“以羽为画”的匠心。工匠需先将金、银片捶揲成底托，再用金丝焊出图案轮廓，形成“嵌羽之槽”。随后，取翠鸟颈间最莹润的羽绒，以特制胶液轻贴于金属胎底。羽丝细软如尘，却需排列得密不透风，方能在光下流转出湖面波光般的幻彩。最后缀以珍珠、翡翠、珊瑚等宝玉石，方成一件雍容典雅的珍品。正如古籍所载：“虽无宝石炫亮，却自有一种艳丽拙朴之美。”\n👑 千年传承，宫廷绝色\n点翠工艺始于汉代，盛于乾隆。昔日的帝王衮服、皇后凤冠，皆以翠羽为饰，历经岁月仍鲜艳如初。一只翠鸟仅能取零星羽绒，修复一顶明代凤冠竟需十万翠羽，其珍贵可见一斑。这项工艺不仅象征着古代匠人的智慧，更承载着东方饰品对细节的执着——以工艺的精细、含蓄之美，诠释“富丽堂皇”的真正内涵。\n🌿 非遗新生，以今承古\n如今，翠鸟已成保护动物，传统点翠逐渐被孔雀羽、染绸等代用品取代。但这项工艺的生命力并未消逝——现代匠人以创新手法延续着点翠的魂韵，让这份“幽蓝幻彩”在当代首饰中重焕生机。非遗的点翠，不再是羽与金的简单结合，而是对千年美学的敬畏与传承。\n点翠的蓝，是时光浸染的诗意，更是工匠指尖流淌的星河。愿这份“永不褪色”的浪漫，能被更多人看见、铭记。','normal','服饰妆造','passed',NULL,'[\"http://te3ceeisz.hn-bkt.clouddn.com/posts/12/1.jpg\", \"http://te3ceeisz.hn-bkt.clouddn.com/posts/12/2.jpg\", \"http://te3ceeisz.hn-bkt.clouddn.com/posts/12/3.jpg\"]','[\"点翠\",\"非遗传承\",\"东方美学\",\"传统工艺美学\"]','public',1,11,1,'2026-03-30 15:51:34','2026-04-28 04:39:10',0,0,'zh','normal',NULL,NULL,0),(13,10023,'窗边一亮，氛围感直接拉满','最先吸引我的是窗边那盏黄灯，布纹透光后很有晚霞感。成品不只是摆件，晚上开灯会把整个角落都照得很温柔。','review','手作体验','passed',NULL,'[\"http://te3ceeisz.hn-bkt.clouddn.com/posts/13/1.jpg\"]','[\"手作灯\",\"布头拼接\",\"氛围感\"]','public',1,49,0,'2026-04-24 18:20:00','2026-04-28 04:39:10',0,0,'zh','review',77,5,0),(14,10000,'拼布排版比想象中还治愈','拼布排版真的比想象中难，但也最有成就感。每一块碎布颜色都不一样，拼在一起反而很耐看，像把记忆缝进了一张图案里。','review','手作体验','passed',NULL,'[\"http://te3ceeisz.hn-bkt.clouddn.com/posts/14/1.jpg\"]','[\"拼布\",\"色块搭配\",\"手作\"]','public',1,31,0,'2026-04-24 17:45:00','2026-04-28 04:39:10',0,0,'zh','review',77,5,0),(15,10020,'缝纫机一响就很有成品感','老师先让我看缝纫机走线，再教我把布边收平。第一次踩踏板还有点紧张，不过看到针脚一条条出来，立刻就有了自己做出来的踏实感。','review','手作体验','passed',NULL,'[\"http://te3ceeisz.hn-bkt.clouddn.com/posts/15/1.jpg\"]','[\"缝纫机\",\"收边\",\"手作过程\"]','public',1,30,0,'2026-04-24 17:10:00','2026-04-28 04:39:10',0,0,'zh','review',77,4,1),(16,10044,'老师手把手帮我调了配色','调整布片位置的时候，才发现细微的错位会影响整体气质。老师帮我把蓝色和粉色重新搭了一下，原本普通的拼片一下子就顺眼了。','review','手作体验','passed',NULL,'[\"http://te3ceeisz.hn-bkt.clouddn.com/posts/16/1.jpg\"]','[\"配色\",\"拼布\",\"老师指导\"]','public',1,30,0,'2026-04-23 20:30:00','2026-04-28 04:39:10',0,0,'zh','review',77,5,0),(17,10045,'经纬线刚上好就很治愈','经纬线刚拉好时还看不出什么，真正开始织之后层次就慢慢出来了。靠近看能看到线面的纹理和手工痕迹，很像把时间一点点织进框里。','review','手作体验','passed',NULL,'[\"http://te3ceeisz.hn-bkt.clouddn.com/posts/17/1.jpg\"]','[\"织机\",\"经纬线\",\"纹理\"]','public',1,23,0,'2026-04-23 18:15:00','2026-04-28 04:39:10',0,0,'zh','review',77,5,0),(18,10007,'小手环做好那刻特别有成就感','小手环虽然不大，但编完以后特别有满足感。毛线颜色一层层过渡，戴在手上轻轻的，像把今天的手作记忆带走了。','review','手作体验','passed',NULL,'[\"http://te3ceeisz.hn-bkt.clouddn.com/posts/18/1.jpg\"]','[\"手环\",\"毛线编织\",\"成就感\"]','public',1,36,0,'2026-04-22 21:00:00','2026-04-28 04:39:10',0,0,'zh','review',77,4,1),(19,10023,'这个灯罩近看也很耐看','这个灯罩近看特别惊喜，拼布边缘收得很利落。白天看是色块和纹理，晚上亮起来又完全变成另一种氛围，细节很耐看。','review','手作体验','passed',NULL,'[\"http://te3ceeisz.hn-bkt.clouddn.com/posts/19/1.jpg\"]','[\"灯罩\",\"细节\",\"布纹\"]','public',1,21,0,'2026-04-22 18:40:00','2026-04-28 04:39:10',0,0,'zh','review',77,5,0),(20,10000,'成品配色很干净','我最喜欢这组图案的配色，碎布块拼起来一点都不乱。成品看着简单，实际上每个颜色的位置都很讲究，最后效果很干净。','review','手作体验','passed',NULL,'[\"http://te3ceeisz.hn-bkt.clouddn.com/posts/20/1.jpg\"]','[\"配色\",\"碎布\",\"成品\"]','public',1,24,0,'2026-04-21 19:05:00','2026-04-28 04:39:10',0,0,'zh','review',77,5,0),(21,10023,'编好手链那一刻特别有成就感','颜色搭配好以后，整条手链一下子就立住了。编织的时候看着绳线一点点成型，收尾完成后真的很想立刻戴上。','review','手作体验','passed',NULL,'[\"http://te3ceeisz.hn-bkt.clouddn.com/posts/21/1.jpg\"]','[\"手链\",\"毛线编织\",\"成就感\"]','public',1,47,1,'2026-04-24 19:10:00','2026-04-28 04:39:10',0,0,'zh','review',78,5,0),(22,10000,'配色一换，手链气质就变了','同样是基础编织，换了颜色后气质完全不同。浅色更清爽，亮色更跳脱，最后成品小小一条却很显眼。','review','手作体验','passed',NULL,'[\"http://te3ceeisz.hn-bkt.clouddn.com/posts/22/1.jpg\"]','[\"配色\",\"手链\",\"织机\"]','public',1,29,0,'2026-04-24 18:45:00','2026-04-28 04:39:10',0,0,'zh','review',78,5,0),(23,10020,'老师带着一步一步编，节奏很舒服','我原本担心自己跟不上，结果老师会一小步一小步带着做。织机和毛线的关系一下子就看明白了，整个过程特别顺。','review','手作体验','passed',NULL,'[\"http://te3ceeisz.hn-bkt.clouddn.com/posts/23/1.jpg\"]','[\"老师指导\",\"织机\",\"手链\"]','public',1,23,0,'2026-04-24 18:10:00','2026-04-28 04:39:10',0,0,'zh','review',78,4,1),(24,10044,'手腕上的小作品越看越喜欢','成品不大，但戴上以后很有存在感。毛线的层次和纹理在光下会变得很明显，看着就很治愈。','review','手作体验','passed',NULL,'[\"http://te3ceeisz.hn-bkt.clouddn.com/posts/24/1.jpg\"]','[\"手环\",\"毛线\",\"成品\"]','public',1,19,0,'2026-04-24 17:35:00','2026-04-28 04:39:10',0,0,'zh','review',78,5,0),(28,10023,'上午的工坊像一段慢镜头','这是一篇普通分享，不是评价。把今天在工坊里拍到的细节整理成九宫格，灯光、桌面和工具都很有现场感。','normal','旅行随记','passed',NULL,'[\"http://te3ceeisz.hn-bkt.clouddn.com/posts/28/1.jpg\"]','[工坊,九宫格,分享]','public',1,12,2,'2026-04-24 22:00:00','2026-04-28 04:39:10',0,0,'zh','normal',NULL,NULL,0),(29,10023,'把体验过程记成一条普通帖子','有些内容更适合放在普通帖子里，先把路线、照片和心情发出来，之后再单独写评价贴。','normal','生活记录','passed',NULL,'[\"http://te3ceeisz.hn-bkt.clouddn.com/posts/29/1.jpg\"]','[生活记录,测试,分享]','public',1,10,1,'2026-04-24 22:10:00','2026-04-28 04:39:10',0,0,'zh','normal',NULL,NULL,0),(30,10023,'普通动态也能显示在我的帖子里','这个测试帖主要用来验证普通分享和评价贴的列表是否分开。现在数据补上后，两个页面应该都能看到内容。','normal','非遗分享','passed',NULL,'[\"http://localhost:8080/uploads/demo/craft-showcase/这个国庆来玩儿毛线编织啊～_7_民艺商店_来自小红书网页版.jpg\"]','[花絮,测试,分享]','private',1,10,0,'2026-04-24 22:20:00','2026-04-27 01:16:13',0,0,'zh','normal',NULL,NULL,0),(31,10011,'纸雕层景 成品展示','纸雕层景背景展示 · 橱窗光影','normal','木版年画','passed',NULL,'[\"http://te3ceeisz.hn-bkt.clouddn.com/posts/31/1.jpg\"]','[\"AI大片\",\"非遗国风\",\"木版年画\",\"橱窗光影\",\"纸雕层景\",\"自适应\"]','public',1,3,0,'2026-04-26 00:17:30','2026-04-28 09:52:04',0,0,'zh','normal',NULL,NULL,0),(32,10011,'匠人工坊 AI大片','以木版年画工坊为主题，木刻印版、朱砂、手工拓印和年节民俗桌面同框，画面朴拙热烈。 · 匠人工坊','normal','服饰妆造','passed',NULL,'[\"http://te3ceeisz.hn-bkt.clouddn.com/posts/32/1.jpg\"]','[\"AI大片\",\"非遗国风\",\"AI非遗大片\"]','public',1,1,0,'2026-04-26 00:53:09','2026-04-28 09:51:59',0,0,'zh','normal',NULL,NULL,0),(33,10000,'面具上色很有仪式感','傩面从打底、勾线到最后上色都很有步骤感，老师会先讲纹样寓意，再慢慢带着调整颜色。戴上成品的时候，感觉自己真的把一段民俗故事做出来了。','review','活动评价','passed',NULL,'[\"http://te3ceeisz.hn-bkt.clouddn.com/posts/33/1.jpg\"]','[\"傩戏\",\"面具雕刻\",\"彩绘\",\"民俗体验\"]','public',1,12,0,'2026-04-27 09:10:00','2026-04-28 04:39:10',0,0,'zh','review',82,5,0),(34,10007,'刀痕和彩绘细节都很扎实','雕刻纹路看着细，但做起来节奏很顺，彩绘后层次一下子就出来了。成品很适合拍照，也能看出工艺里的认真劲。','review','活动评价','passed',NULL,'[\"http://te3ceeisz.hn-bkt.clouddn.com/posts/34/1.png\"]','[\"傩戏\",\"上色\",\"传统工艺\",\"体验\"]','public',1,9,0,'2026-04-27 09:14:00','2026-04-28 04:39:10',0,0,'zh','review',82,4,0),(45,10000,'青花纹样上手就很出片','先打底再勾线，蓝白对比很清爽，老师还会提醒留白和落笔力度。做完以后杯面一样的纹样很耐看。','review','活动评价','passed',NULL,'[\"http://te3ceeisz.hn-bkt.clouddn.com/posts/45/1.jpg\"]','[\"青花瓷\",\"彩绘\",\"蓝白\",\"纹样\"]','public',1,15,0,'2026-04-27 09:58:00','2026-04-28 04:39:10',0,0,'zh','review',88,5,0),(46,10023,'颜色偏少但很考验手感','青花看着简单，其实勾线和晕染都得稳住，稍微手抖就会影响线条。过程不算轻松，但能学到很多。','review','活动评价','passed',NULL,'[\"http://te3ceeisz.hn-bkt.clouddn.com/posts/46/1.jpg\"]','[\"青花瓷\",\"勾线\",\"手感\",\"体验\"]','public',1,5,0,'2026-04-27 10:02:00','2026-04-28 04:39:10',0,0,'zh','review',88,3,0),(47,10020,'傩面细节越看越有味道','面具的线条和上色层次特别稳，做完以后回头看会发现每一刀都有讲究。成品很有舞台感，适合展示民俗审美。','review','活动评价','passed',NULL,'[\"http://te3ceeisz.hn-bkt.clouddn.com/posts/47/1.jpg\"]','[\"傩戏\",\"面具\",\"彩绘\",\"展示\"]','public',1,6,0,'2026-04-27 10:10:00','2026-04-28 04:39:10',0,0,'zh','review',82,4,0),(48,10023,'这门手艺很适合慢慢做','雕刻和涂色都需要稳住节奏，最后完成的时候会特别有成就感。成品细看很扎实，能感受到传统工艺的耐心。','review','活动评价','passed',NULL,'[\"http://te3ceeisz.hn-bkt.clouddn.com/posts/48/1.jpg\"]','[\"傩戏\",\"手作\",\"传统工艺\",\"耐心\"]','public',1,5,0,'2026-04-27 10:14:00','2026-04-28 04:39:10',0,0,'zh','review',82,5,0),(49,10044,'青花的蓝很耐看','青花瓷最吸引人的就是蓝白之间的干净感，勾线完成以后整个器型一下子就立住了。拍照和摆放都很出效果。','review','活动评价','passed',NULL,'[\"http://te3ceeisz.hn-bkt.clouddn.com/posts/49/1.jpg\"]','[\"青花瓷\",\"蓝白\",\"纹样\",\"彩绘\"]','public',1,9,0,'2026-04-27 10:18:00','2026-04-28 04:39:10',0,0,'zh','review',88,5,0),(50,10045,'上色过程比想象中更治愈','一笔一笔把纹样补完整的过程很安静，也很解压。成品的线条很顺，放在灯下会更显温润。','review','活动评价','passed',NULL,'[\"http://te3ceeisz.hn-bkt.clouddn.com/posts/50/1.jpg\"]','[\"青花瓷\",\"上色\",\"治愈\",\"体验\"]','public',1,4,0,'2026-04-27 10:22:00','2026-04-28 04:39:10',0,0,'zh','review',88,4,0),(51,10000,'苏绣针法很细腻','老师先带着看针法走向，再一点点做纹样层次。真正上手后会发现苏绣最迷人的地方就是细，做完以后很有江南气质。','review','活动评价','passed',NULL,'[\"http://te3ceeisz.hn-bkt.clouddn.com/posts/51/1.jpg\"]','[\"苏绣\",\"针法\",\"刺绣\",\"江南\"]','public',1,8,0,'2026-04-27 11:00:00','2026-04-28 04:39:10',0,0,'zh','review',70,5,0),(52,10007,'配色和收边都很讲究','一针一线看着慢，但完成以后特别耐看。绣面收边很整齐，颜色也搭得很温柔，成品拿在手里很舒服。','review','活动评价','passed',NULL,'[\"http://te3ceeisz.hn-bkt.clouddn.com/posts/52/1.png\"]','[\"苏绣\",\"配色\",\"收边\",\"手作\"]','public',1,6,0,'2026-04-27 11:05:00','2026-04-28 10:11:18',0,0,'zh','review',70,4,0),(53,10020,'越做越能感受到耐心','前面总担心自己做不整齐，后来跟着节奏慢慢就顺了。苏绣最打动人的不是快，而是那种沉下来的工夫。','review','活动评价','passed',NULL,'[\"http://te3ceeisz.hn-bkt.clouddn.com/posts/53/1.jpg\"]','[\"苏绣\",\"耐心\",\"绣面\",\"体验\"]','public',1,5,0,'2026-04-27 11:10:00','2026-04-28 10:11:16',0,0,'zh','review',70,4,0),(54,10023,'京剧脸谱一上色就很有戏','勾线、填色、修正，每一步都很像在给角色“定神”。做完以后面具的气势立刻就出来了。','review','活动评价','passed',NULL,'[\"http://te3ceeisz.hn-bkt.clouddn.com/posts/54/1.jpg\"]','[\"京剧脸谱\",\"上色\",\"戏曲\",\"面具\"]','public',1,8,0,'2026-04-27 11:15:00','2026-04-28 10:11:14',0,0,'zh','review',4,5,0),(55,10044,'颜色对比很抓眼','红蓝金的搭配特别出效果，老师会解释不同颜色在脸谱里的含义。不是单纯涂色，更像在读一张戏曲名片。','review','活动评价','passed',NULL,'[\"http://te3ceeisz.hn-bkt.clouddn.com/posts/55/1.jpg\", \"http://te3ceeisz.hn-bkt.clouddn.com/posts/55/2.jpg\"]','[\"京剧脸谱\",\"配色\",\"戏曲文化\",\"体验\"]','public',1,7,0,'2026-04-27 11:20:00','2026-04-28 10:11:12',0,0,'zh','review',4,4,0),(56,10045,'昆山腔身段很优雅','跟着老师做身段的时候，会明显感觉动作幅度和气息都要拿捏到位。整个体验特别有戏曲韵味。','review','活动评价','passed',NULL,'[\"http://te3ceeisz.hn-bkt.clouddn.com/posts/56/1.jpg\", \"http://te3ceeisz.hn-bkt.clouddn.com/posts/56/2.jpg\"]','[\"昆山腔\",\"身段\",\"戏曲\",\"体验\"]','public',1,7,0,'2026-04-27 11:25:00','2026-04-28 10:11:10',0,0,'zh','review',15,5,0),(57,10000,'动作和唱腔都很有味道','老师会先拆开讲每个动作的来由，再配着唱腔一起练。虽然不容易，但越学越能体会昆山腔的细腻。','review','活动评价','passed',NULL,'[\"http://te3ceeisz.hn-bkt.clouddn.com/posts/57/1.jpg\"]','[\"昆山腔\",\"唱腔\",\"身段\",\"传统戏曲\"]','public',1,5,0,'2026-04-27 11:30:00','2026-04-28 10:11:08',0,0,'zh','review',15,3,0),(58,10007,'川剧变脸现场感很强','近距离看变脸真的很震撼，动作一气呵成。老师讲了脸谱和节奏的关系，体验完对川剧一下子就有概念了。','review','活动评价','passed',NULL,'[\"http://te3ceeisz.hn-bkt.clouddn.com/posts/58/1.jpg\"]','[\"川剧变脸\",\"节奏\",\"戏曲\",\"舞台\"]','public',1,10,0,'2026-04-27 11:35:00','2026-04-28 10:11:07',0,0,'zh','review',28,5,0),(59,10020,'看一遍还想再看','变脸的切换很快，但细节又特别讲究。舞台感很足，整个过程看完会很想继续了解川剧。','review','活动评价','passed',NULL,'[\"http://te3ceeisz.hn-bkt.clouddn.com/posts/59/1.jpg\"]','[\"川剧变脸\",\"舞台\",\"戏曲\",\"观演\"]','public',1,6,0,'2026-04-27 11:40:00','2026-04-28 10:11:05',0,0,'zh','review',28,4,0),(60,10023,'节奏卡得特别准','最喜欢的是老师对节奏的把控，表演和讲解穿插得刚好。就算是第一次看，也不会觉得距离感很强。','review','活动评价','passed',NULL,'[\"http://te3ceeisz.hn-bkt.clouddn.com/posts/60/1.jpg\"]','[\"川剧变脸\",\"节奏\",\"讲解\",\"体验\"]','public',1,5,0,'2026-04-27 11:45:00','2026-04-28 10:11:03',0,0,'zh','review',28,4,0),(61,10044,'唐三彩的釉色很漂亮','器型和釉色搭在一起很有古意，尤其是黄绿之间的过渡很自然。做完之后会更理解唐三彩为什么这么耐看。','review','活动评价','passed',NULL,'[\"http://te3ceeisz.hn-bkt.clouddn.com/posts/61/1.jpg\", \"http://te3ceeisz.hn-bkt.clouddn.com/posts/61/2.jpg\"]','[\"唐三彩\",\"釉色\",\"器型\",\"彩绘\"]','public',1,8,0,'2026-04-27 11:50:00','2026-04-28 10:11:01',0,0,'zh','review',45,5,0),(62,10045,'上手以后更有历史感','一边上色一边听器型故事，感觉不是在做普通手工，而是在碰一段很具体的唐代审美。','review','活动评价','passed',NULL,'[\"http://te3ceeisz.hn-bkt.clouddn.com/posts/62/1.jpg\", \"http://te3ceeisz.hn-bkt.clouddn.com/posts/62/2.jpg\"]','[\"唐三彩\",\"历史感\",\"器型\",\"体验\"]','public',1,5,0,'2026-04-27 11:55:00','2026-04-28 05:16:16',0,0,'zh','review',45,5,0),(63,10000,'123','qwe','normal','服饰妆造','deleted',NULL,'[\"http://te3ceeisz.hn-bkt.clouddn.com/posts/63/1.png\"]','[]','public',0,1,0,'2026-04-28 12:13:08','2026-04-28 12:13:40',0,0,'en','normal',NULL,0,0);
